programs.haiku:
"""Closing brackets that end a long group.

A closing bracket (")", "]", "}", and tokens made of them, like "}}\\n" or " });\\n")
is strongly active when it closes a group that was opened many tokens earlier, the
end of a multi-token block or call, and weakly active when it closes a bracket opened
just before (f(x), a[i]). Other delimiter tokens (backslashes, quotes, angle brackets,
dollar signs, opening brackets) get a small constant; ordinary words get 0.
"""
import math

READS = ()
PAIRS = {")": "(", "]": "[", "}": "{"}
OPEN = set("([{")
DELIMS = set("\\\"'<>$")

def strength(dist):
    # log-scaled: ~0 for brackets closed within 4 tokens, saturating near 1.1 after ~64
    if dist is None:
        return 0.67  # closes a bracket opened before this document window
    if dist <= 4:
        return 0.0
    return min(1.1, 0.35 * math.log2(dist / 4))

def step(carry, prefix, upstream):
    stack, doc = carry if carry else ([], None)
    pos = prefix.position
    if prefix.document_ids[-1] != doc:
        stack, doc = [], prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    value = 0.0
    for ch in token:
        if ch in OPEN:
            stack.append((ch, pos))
            value = max(value, 0.05)
        elif ch in PAIRS:
            dist = None
            for k in range(len(stack) - 1, -1, -1):
                if stack[k][0] == PAIRS[ch]:
                    dist = pos - stack[k][1]
                    del stack[k:]
                    break
            value = max(value, strength(dist))
        elif ch in DELIMS:
            value = max(value, 0.05)
    if "\n" in token and value > 0.05:
        value *= 0.8
    return (stack, doc), value

programs.sol:
"""Approximate a strong negative response to adjacent unmarked base letters.

The main rules cover South Asian scripts: consonants after consonants (or
bare independent A) are negative; vowel signs and viramas mostly are not.
Nasality, aspiration and gemination signs have separate rules. The last
completed character is remembered, resetting at document boundaries.
Incomplete UTF-8 tokens use named script-block prefixes; their completions
use the actual decoded character. Smaller rules cover Sinhala, Myanmar,
Tibetan, Thai and Arabic; remaining text is near zero.
"""
import unicodedata as ud

READS = ()

# Whole consonant, unfinished lower-half prefix, byte completion, upper prefix:
# negative strengths when the preceding completed character is a consonant.
STRENGTHS = {
    'Devanagari': (3.4, 2.35, 2.25, 0.8),
    'Bengali': (3.75, 3.05, 1.8, 1.35),
    'Gurmukhi': (2.3, 1.9, 2.15, 1.1),
    'Gujarati': (3.45, 3.85, 3.3, 0.1),
    'Oriya': (3.5, 3.35, 3.4, 0.1),
    'Tamil': (4.05, 3.3, 3.25, 0.05),
    'Telugu': (4.25, 3.65, 4.1, 0.1),
    'Kannada': (4.2, 3.2, 3.4, 0.2),
    'Malayalam': (3.7, 2.25, 3.3, 0.15),
}
BLOCKS = (
    ('Devanagari', 0x0900, 0x0980), ('Bengali', 0x0980, 0x0A00),
    ('Gurmukhi', 0x0A00, 0x0A80), ('Gujarati', 0x0A80, 0x0B00),
    ('Oriya', 0x0B00, 0x0B80), ('Tamil', 0x0B80, 0x0C00),
    ('Telugu', 0x0C00, 0x0C80), ('Kannada', 0x0C80, 0x0D00),
    ('Malayalam', 0x0D00, 0x0D80), ('Sinhala', 0x0D80, 0x0E00),
    ('Thai', 0x0E00, 0x0E80), ('Tibetan', 0x0F00, 0x1000),
    ('Myanmar', 0x1000, 0x10A0), ('Arabic', 0x0600, 0x0700),
)
# These IDs encode the first two UTF-8 bytes, optionally preceded by a space.
# They name Unicode byte ranges, not a vocabulary of learned word exceptions.
PREFIXES = (
    ((5502, 14925), 'Devanagari', 'low'),    # E0 A4
    ((12619,), 'Devanagari', 'high'),       # E0 A5
    ((11125, 35178), 'Bengali', 'low'),     # E0 A6
    ((26927,), 'Bengali', 'high'),          # E0 A7
    ((39317, 69033), 'Gurmukhi', 'low'),    # E0 A8
    ((65877,), 'Gurmukhi', 'high'),         # E0 A9
    ((40714, 94491), 'Gujarati', 'low'),    # E0 AA
    ((72219,), 'Gujarati', 'high'),        # E0 AB
    ((124593,), 'Oriya', 'low'),           # E0 AC
    ((31305, 93255), 'Telugu', 'low'),      # E0 B0
    ((52798,), 'Telugu', 'high'),           # E0 B1
    ((20026, 70597), 'Tamil', 'low'),       # E0 AE
    ((31501,), 'Tamil', 'high'),            # E0 AF
    ((33556, 89434), 'Kannada', 'low'),     # E0 B2
    ((55890,), 'Kannada', 'high'),          # E0 B3
    ((33739,), 'Malayalam', 'low'),        # E0 B4
    ((50111,), 'Malayalam', 'high'),        # E0 B5
    ((54642,), 'Sinhala', 'low'),           # E0 B6
    ((48749,), 'Sinhala', 'high'),          # E0 B7
    ((62416,), 'Tibetan', 'low'),           # E0 BD, base letters
    ((24831,), 'Myanmar', 'low'),           # E1 80, letters/signs
)


def character(c):
    code = ord(c)
    if code < 0x0600:
        return '', ''
    script = next((s for s, lo, hi in BLOCKS if lo <= code < hi), '')
    if not script:
        return '', ''
    kind, name = ud.category(c)[0], ud.name(c, '')
    if script == 'Thai' and c in 'ะาำเแโใไ':
        return script, 'vowel'
    if script == 'Thai' and 0x0E48 <= code <= 0x0E4B:
        return script, 'tone'
    if script == 'Arabic' and c in 'اآأإٱوؤيیىئ':
        return script, 'vowel'
    if any(x in name for x in ('ANUSVARA', 'CANDRABINDU', 'BINDI', 'TIPPI')):
        kind = 'nasal'
    elif 'VISARGA' in name:
        kind = 'breath'
    elif 'ADDAK' in name:
        kind = 'gemination'
    elif 'VIRAMA' in name or 'PULLI' in name:
        kind = 'link'
    elif kind == 'M':
        kind = 'mark'
    elif kind == 'L' and script == 'Sinhala':
        kind = 'consonant' if 0x0D9A <= code <= 0x0DC6 else 'vowel'
    elif kind == 'L' and script in {'Myanmar', 'Tibetan'}:
        kind = 'consonant'
    elif kind == 'L' and script in STRENGTHS:
        if name.endswith('LETTER A'):
            kind = 'bare_a'
        elif any(x in name for x in ('LETTER A', 'LETTER I', 'LETTER U',
                                     'LETTER E', 'LETTER O', 'VOCALIC')):
            kind = 'vowel'
        else:
            kind = 'consonant'
    return script, kind


def estimate(script, kind, piece, previous):
    base = previous in {'consonant', 'bare_a'}
    if script in STRENGTHS:
        whole, lead, finish, upper = STRENGTHS[script]
        if kind == 'nasal':
            return -(3.1 if script == 'Gurmukhi' else 3.8) if base else 0.2
        if kind in {'breath', 'gemination'}:
            return -1.8 if kind == 'breath' else -1.0
        if kind == 'link':
            return 0.15
        if kind == 'mark':
            return -0.06 if piece == 'multi' else 0.12
        if kind in {'low', 'high'}:
            if base:
                return -lead if kind == 'low' else -upper
            if previous == 'nasal' and script == 'Gurmukhi':
                return -0.68
            if previous in {'mark', 'link'}:
                return 0.7 if kind == 'low' else -0.1
            return -0.3
        if kind == 'consonant' and piece != 'multi':
            if base:
                return -finish if piece == 'byte' else -whole
            if previous == 'start':
                return -0.6
            if previous == 'nasal' and script == 'Gurmukhi' and piece == 'byte':
                return -0.75
            return -0.2 if previous == 'vowel' else 0.0
    elif script in {'Sinhala', 'Myanmar', 'Tibetan'}:
        if kind in {'consonant', 'low'} and piece != 'multi':
            if previous != 'start':
                return -0.6 if script == 'Tibetan' else -1.4
            return -0.6 if script == 'Myanmar' else 0.0
    elif script == 'Thai':
        if kind == 'L' and piece == 'single' and previous == 'L':
            return -0.25
        if kind == 'tone':
            return -0.05
        if kind == 'mark':
            return 0.08 if piece == 'single' else 0.025
    elif script == 'Arabic':
        if kind == 'mark' or previous == 'mark':
            return -0.1
        if kind == 'L' and piece == 'single' and previous in {'L', 'vowel'}:
            return -0.1
    return 0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    _, last_script, last_kind = (doc, '', '') if reset else carry
    s = prefix.token_strings[-1]
    body, spaced = s.lstrip(), bool(s and s[0].isspace())
    script, kind, piece = '', '', 'single'
    completed = body.rstrip('\ufffd')
    if body and body[0] != '\ufffd':
        script, kind = character(body[0])
        piece = 'single' if len(body) == 1 else 'multi'
    elif body:
        for ids, block, band in PREFIXES:
            if prefix.token_ids[-1] in ids:
                script, kind, piece = block, band, 'prefix'
                break
        else:
            if not reset:
                c = prefix.text_prefixes[-1][-1]
                if c != '\ufffd':
                    script, kind = character(c)
                    piece, completed = 'byte', c
    previous = last_kind if script == last_script and not spaced else 'start'
    value = estimate(script, kind, piece, previous)
    if completed:
        last_script, last_kind = character(completed[-1])
    elif spaced:
        last_script, last_kind = '', ''
    return (doc, last_script, last_kind), float(value)

"""Approximate a capital-letter suffix detector.

The main response is negative on a digit immediately after a capital, as
in F1 or BRCA2. A one-letter lowercase continuation also triggers it.
Separators and subscript notation give weaker responses, including the
next number when one intervening separator is present. Longer lowercase
continuations have a small positive response. Other tokens are near zero.
The two-token memory is reset whenever the document label changes.
"""
READS = ()
SUBSCRIPT = {'_', '_{', '}_{', '}_', '$_'}
HYPHENS = {'-', '−', '‐', '–'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev, before = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    capital = bool(prev) and prev[-1].isupper()
    earlier_capital = bool(before) and before[-1].isupper()
    value = 0.0

    if capital:
        if token.isdecimal():
            value = -2.03 if prev[-1].isascii() else -1.1
        elif token.isdigit():
            value = -1.4 if token in '₀₁₂₃₄₅₆₇₈₉' else -0.6
        elif len(token) == 1 and token.islower():
            value = -1.13 if token.isascii() and prev[-1].isascii() else -0.25
        elif token.isalpha() and token.islower():
            value = 0.06
        elif token == ' ':
            value = -0.49
        elif token.isspace():
            value = 0.06 if '\n' in token else -0.20
        elif token in HYPHENS or token in ("'", '^', '^{', '+'):
            value = -0.75
        elif token in SUBSCRIPT:
            value = -0.44 if token == '_' else -0.58
        elif token in ('$', '\\'):
            value = -0.58
        elif token in ('/', '('):
            value = -0.25
        elif len(token) == 2 and token[0] in ' -_' and token[1].islower():
            value = -0.35 if token[0] == ' ' else -0.70
        elif token == '�':
            value = -0.35
    elif token.isdecimal():
        if earlier_capital:
            if prev == ' ':
                value = -1.03
            elif prev in SUBSCRIPT:
                value = -0.88 if prev == '_' else -1.3
            elif prev in HYPHENS or prev in ('^', '^{', '(', '/'):
                value = -0.5
            elif prev == '$':
                value = -0.82
        elif before and before[-1].islower() and prev in SUBSCRIPT:
            value = -0.40
        if value == 0.0 and prev and prev[-1].islower():
            value = -0.06
    elif token in '₀₁₂₃₄₅₆₇₈₉' and len(token) == 1:
        value = -0.27
    elif earlier_capital and prev in SUBSCRIPT:
        if len(token) == 1 and token.islower():
            value = -0.68

    return (doc, token, prev), float(value)

programs.haiku:
"""Characters glued onto a capital letter (codes, acronyms, gene and chemical names).

This component (layer 0, MLP down-projection, feature 2627) goes strongly negative on the
character that continues a capital letter, with no space in between or with a short
separator:

- a digit right after a capital letter: the 6 in "TRAF6", the 2 in "IL2" or "CO2",
  the 1 in "Table S1": about -2.0;
- a digit after a capital letter with a space, underscore or dot between: "GMAT 1",
  "P_1", "E_2": about -1.0;
- a single lowercase letter right after a capital, as in the plural "s" of "MNCs": -1.1;
- a hyphen or apostrophe right after a capital, as in "DNP-": about -0.8.

Everything else predicts 0. The rule looks only at the newest tokens.
"""

READS = ()

DIGITS = set("0123456789")
LOWER = set("abcdefghijklmnopqrstuvwxyz")
SEPARATORS = {" ", "_", "_{", "."}


def ends_in_capital(text):
    """True if the token, without its leading space, is ASCII and ends in A-Z."""
    text = text.strip()
    return bool(text) and text.isascii() and "A" <= text[-1] <= "Z"


def step(carry, prefix, upstream):
    """This component's activation at the newest token of the prefix."""
    n = len(prefix)
    if n < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    cur, prev = prefix.token_strings[-1], prefix.token_strings[-2]
    if cur and all(c in DIGITS for c in cur) and not cur.startswith(" "):
        if ends_in_capital(prev):
            return None, -2.0
        if prev in SEPARATORS and n >= 3 and ends_in_capital(prefix.token_strings[-3]):
            return None, -1.0
        return None, 0.0
    if cur.startswith(" ") or not ends_in_capital(prev):
        return None, 0.0
    if cur in LOWER:
        return None, -1.1
    if cur in ("-", "'"):
        return None, -0.8
    return None, 0.0

programs.sol:
"""Approximate a mostly negative response to the letter U.

Capital U is strongest as a separate token, especially after an article.
It is weaker in capital-letter sequences and prime-marked notation.
Lowercase u, fullwidth U, punctuation joined to U, and short U-initial
fragments have smaller responses. United and University are common longer
U-initial forms; the latter also leaves a response on its following 'of'.
Other tokens are left at zero: this captures the main pattern, not every
small lexical or contextual fluctuation of the component.
"""

READS = ()
ARTICLES = {'a', 'an', 'the'}
PRIME_MARKS = {"'", '′', '’'}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != document else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    last = previous[-1:]
    spaced = token.startswith(' ')

    if word == 'U':
        if not previous:
            value = -2.51 if spaced else -3.68
        elif last.isupper():
            value = -1.35 if spaced else -0.78
        elif spaced and previous.strip() in PRIME_MARKS:
            value = -1.5
        elif spaced and previous.strip().lower() in ARTICLES:
            value = -2.8
        elif last.islower():
            value = -2.54 if spaced else -1.97
        elif last.isdigit():
            value = -2.22 if spaced else -2.04
        else:
            value = -1.97 if spaced else -2.18
    elif word == 'Ｕ':
        value = -1.0
    elif word == 'u':
        value = -0.33 if spaced else (-0.15 if last.isalpha() else -0.28)
    elif word.endswith('U') and all(not c.isalnum() for c in word[:-1]):
        value = -1.25
    elif word == 'United':
        value = -0.47
    elif word == 'University':
        value = -0.51 if previous.strip().istitle() else -0.32
    elif word.startswith('U'):
        value = (-0.28 if spaced else -0.11) if len(word) == 2 else -0.05
    elif word == 'of' and previous.strip() == 'University':
        value = -0.35
    elif word == '.S' and previous.strip() == 'U':
        value = -0.16
    else:
        value = 0.0
    return (document, token), value

programs.luna:
"""Mark a standalone capital U, especially when preceded by a word space."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == " U":
        return None, -2.24
    if token == "U":
        return None, -1.56
    return None, 0.0

programs.sol:
"""Sparse spelling rules, mainly for short 'ho' fragments.

The negative response is largest on 'ho' itself and when an h/o spelling
crosses a token boundary. It weakens in longer words, has a few common-word
exceptions, and recognizes Japanese/Korean ho. Hours are stronger after
vague quantities. A separate positive rule recognizes term(s), especially
following ordinals. Smaller rules cover nearby h spellings and o-like zero.
Only the previous token is carried; documents reset that context. Scattered
weak token-specific responses are deliberately not memorized.
"""
READS = ()
TERM_MODIFIERS = {
    'first', 'second', 'third', 'fourth', 'fifth', 'sixth', 'seventh',
    'eighth', 'ninth', 'tenth', 'nth', 'st', 'nd', 'rd', 'th', 'mixed',
}


def ho_strength(s):
    if s == 'ho':
        return -1.95
    if s in {'hour', 'hours'}:
        return -0.7
    if s in {'home', 'hook', 'hold'} or s.startswith('how'):
        return 0.0
    if len(s) == 3:
        return {'r': -1.3, 'l': -0.8, 't': -0.65,
                'n': -0.4, 'm': -0.23}.get(s[2], -0.6)
    if len(s) == 4:
        if s[2:] in {'ax', 'op'}:
            return -1.1
        return -0.55 if s[2] == 'o' else -0.15
    return -0.1


def split_ho(raw, previous):
    s = raw.lower()
    if s.startswith('ow'):
        return 0.0
    if len(s) == 1:
        value = -0.65 if s == 'ö' else -1.8
    elif len(s) == 2:
        value = -0.55 if s[1] in 'nlmt' else -1.1
        if s[1] == 'h':
            value = -2.0
    else:
        value = -0.9 if len(s) < 6 else -0.4
    if len(previous.lstrip(' \t\n_-./(')) > 2 and len(s) > 1:
        value *= 0.6
    if previous.lower().endswith('ch'):
        value *= 0.55
    elif previous.endswith('ph'):
        value *= 0.75
    if previous[-1].isupper() or previous.lstrip(' \t\n_-./(')[:1].isupper():
        value *= 1.25
    if previous.lower().endswith('-h') and len(s) == 1:
        value = -3.5
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = '' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    body = raw.lstrip(' \t\r\n_-./(')
    s, left = body.lower(), prev.strip().lower()
    joined = bool(raw) and not raw[0].isspace()
    value = 0.0
    if s.startswith('ho'):
        value = ho_strength(s)
        if s == 'ho':
            value -= 0.7 if body[0].isupper() else 0.0
            if joined and prev.endswith('n'):
                value *= 0.75  # nh, as in Portuguese caminho
    elif joined and raw[0].lower() in 'oóòôöōõ' and prev.lower().endswith('h'):
        value = split_ho(raw, prev)
    elif s in {'ホ', 'ほ', '호'}:
        value = -2.15 if s == 'ホ' else -1.15
    elif raw.startswith('о') and left.endswith(tuple('хшщ')):
        value = -0.4
    elif s == 'fo':
        value = -0.65 if raw.startswith(' ') else -0.35
    elif s in {'ha', 'hu', 'hö', 'hh'}:
        value = {'ha': -0.2, 'hu': -0.22, 'hö': -0.35, 'hh': -0.6}[s]
    elif s in {'term', 'terms'}:
        value = 0.22 if s == 'term' else 0.12
        if left in TERM_MODIFIERS:
            value += 0.58 if s == 'term' else 0.4
    elif joined and prev.lower().endswith('h'):
        value = {'0': -0.65, 'h': -0.7, 'a': -0.4, 'u': -0.6,
                 'is': 0.7, 'int': 0.7, 'ints': 0.7}.get(s, 0.0)
    elif s == 'h':
        value = -0.25 if raw[:1] in '-.' else -0.04
        if not prev:
            value = -0.65 if body.isupper() else -1.0
    if s in {'hour', 'hours'}:
        if left.isdigit():
            value = -0.58 if s == 'hours' else -0.43
        elif left in {'few', 'many', 'several'}:
            value = -1.3
        elif s == 'hour' and left == 'an':
            value = -0.85
    return (doc, raw), float(value)

programs.haiku:
"""Layer-0 MLP output unit 2629: a spelled-"ho" detector, and "term" after an ordinal.

It is negative where the letters "ho" are spelled: on the bare token "ho" (any case), on
the short word-start pieces hol, hor, hot, hour(s), hood, hon, and on an "o" that starts a
token right after a token ending in "h" (rh|omb, h|oll, Rh|ô), so "ho" is split across a
boundary. Common whole words such as how, home, house, hold and host stay near zero.
It is positive on "term" right after an ordinal ("the third term"), and weakly on other "term"s.
Everything else is predicted as 0.
"""

READS = ()

ORDINALS = {"first", "second", "third", "fourth", "fifth", "sixth", "seventh", "eighth", "ninth", "tenth"}
HO_PIECES = {"hol", "hor", "hot", "hour", "hours", "hood", "hon"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if cur == "ho":
        value = -2.0
    elif cur in HO_PIECES:
        value = -0.7
    elif prev.endswith("h") and cur[:1] in ("ô", "ö"):
        value = -0.6
    elif prev.endswith("h") and cur[:1] == "o":
        value = -0.35
    elif cur in ("term", "terms"):
        value = 0.8 if prev in ORDINALS else 0.15
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Lexical references to unspecified people, opposed to water-place words.

Someone/anyone/everyone are strongest; person, who, one, and indefinite
things or places are weaker. A few local phrases strengthen the response.
Lake, bay and river words have the opposite sign. These are responses to
spellings, not semantic disambiguation: a water word may occur in a name.
Unlisted tokens receive zero; small, idiosyncratic responses are omitted.
"""
READS = ()

HUMAN_PRONOUNS = {
    'someone': 4.79, 'anyone': 4.17, 'everyone': 4.32,
    'somebody': 3.86, 'anybody': 3.54, 'everybody': 3.04,
    'nobody': 2.92, 'whoever': 3.02,
}
OTHER_REFERENCES = {
    'something': 1.33, 'anything': 1.44, 'everything': 1.50,
    'nothing': 1.12, 'somewhere': 1.13, 'anywhere': 1.08,
    'everywhere': 0.93, 'elsewhere': 0.93, 'nowhere': 0.74,
    'people': 0.85, 'persons': 1.01, 'whom': 0.49, 'whose': 0.30,
    'those': 0.74, 'ones': 0.26, 'these': 0.09,
    'member': 0.50, 'members': 0.31, 'owner': 0.41, 'viewer': 0.37,
}
# Some translations of indefinite pronouns and generic people references.
FOREIGN_REFERENCES = {
    '人': 0.48, '的人': 0.93, '有人': 2.72, '大家': 1.07,
    '谁': 2.26, '誰': 2.06, '是谁': 2.15,
    '没有人': 2.27, '没人': 2.14, '每个人': 1.95,
