"""Estimate responses to English connecting phrases.

The strongest positive estimates are for 'so that' and 'such that',
followed by 'terms of' and weaker clause introductions. Infinitival 'to'
after knowledge, decision, agreement, failure, or appearance words gets
negative estimates. A few duration and idiom fragments and capitalized
'That' have separate estimates; unmatched tokens get zero.

Keep only the last 100 characters, resetting at document boundaries.
This joins split English words and recognizes 'so/such ... that' with up
to three intervening words. Initial 'so' gets a positive estimate too.
Coefficients approximate training means, not all the component's small,
idiosyncratic token responses.
"""
import re

READS = ()
HYPOTHESES = {'assume', 'assumes', 'assumed', 'assuming', 'assumption',
              'hypothesis', 'given'}
ASSURANCES = {'ensure', 'ensures', 'ensured', 'ensuring', 'sure'}
IMPLICATIONS = {'mean', 'means', 'meaning', 'meant', 'follows'}
DECISIONS = {'decide', 'decides', 'decided', 'agree', 'agrees', 'agreed'}
FAILURES_OR_APPEARANCES = {'fail', 'fails', 'failed', 'appear', 'appears',
                         'appeared', 'said', 'claimed', 'promised'}
CLAUSE_PROMPTS = HYPOTHESES | ASSURANCES | IMPLICATIONS
DURATIONS = {'years', 'months', 'minutes', 'times'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    match = re.search(r'([A-Za-z]+)$', tail)
    previous = match[1].lower() if match else ''
    value = 0.45 if not tail and word == 'so' else 0.0
    if word == 'that':
        if token.strip() == 'That':
            value = -0.14
        elif previous == 'so':
            value = 1.95 if match[1] == 'So' else 2.2
        elif previous == 'such':
            value = 1.22
        elif previous == 'now':
            value = 0.9 if match[1] == 'Now' else 0.57
        elif previous == 'suppose':
            value = 0.7
        elif (link := re.search(
                r'\b(so|such)((?: [A-Za-z]+){1,3})$', tail.lower())):
            gap = len(link[2].split()) - 1
            value = (0.85 * 0.55 ** gap if link[1] == 'so'
                     else 0.75 * 0.7 ** gap)
        elif previous in CLAUSE_PROMPTS:
            value = 0.37
        elif previous == 'but':
            value = 0.41
        elif previous == 'way':
            value = 0.5
        elif previous in {'ways', 'manner', 'condition', 'case'}:
            value = 0.27
        elif previous == 'enough':
            value = 0.4
        elif tail.endswith(','):
            value = 0.17
    elif word == 'of':
        if previous == 'terms':
            value = 0.86
        elif previous == 'term':
            value = 0.5
        elif previous in DURATIONS:
            value = 0.23
        elif previous in {'place', 'instead'}:
            value = 0.18
    elif word == 'to':
        if previous == 'known':
            value = -0.8
        elif previous in DECISIONS:
            value = -0.67
        elif previous in FAILURES_OR_APPEARANCES:
            value = -0.5
        elif previous in {'decision', 'failure'}:
            value = -0.38
        elif previous == 'ability':
            value = -0.23
    elif word == 'as' and previous == 'so':
        value = 0.45
    elif word == 'terms' and previous == 'in':
        value = 0.26
    elif word in {'turn', 'mind'} and previous == 'in':
        value = -0.39
    return (doc, (tail + token)[-100:]), value

programs.haiku:
"""Layer-0 MLP unit 2631 (down_proj): a "that opens a clause of result or supposition"
detector, with a few related words.

Plain-language rule, applied to the word just typed (the token at this position):
- "that" right after "so" gives a strong response (about 2.1): the "so that" result clause.
- "that" right after "such" gives a fairly strong response (about 1.2): "such that".
- "that" after words of supposing, intending or stating a condition ("suppose", "assume",
  "ensure", "means", "given", "but", "way", "sure", "now") gives a moderate one (about 0.45).
- "that" after verbs of finding, checking or reporting ("found", "verify", "mention",
  "confirm") is slightly negative (about -0.15); other "that" is near zero (about 0.05).
- "of" right after "terms" or "term" ("in terms of") gives about 0.75; "of" after nouns of
  time, measure or manner ("years of", "place of", "levels of") about 0.2.
- "to" right after verbs of deciding, agreeing or failing ("decided to", "failed to",
  "known to") is negative (about -0.55); "to" after "go", "enough", "ready", "time" about 0.2.
- The word right after "so" (other than "that") gets a small 0.1.
Everything else is 0. Activation values are in the component's own units.
"""

READS = ()

RESULT_WORDS = {"so"}
SUCH_WORDS = {"such"}
SUPPOSE_WORDS = {"suppose", "assume", "assuming", "assumed", "given", "ensure", "ensuring",
                 "ensures", "sure", "means", "mean", "meaning", "way", "but", "hope", "now",
                 "provided", "expected"}
FIND_WORDS = {"find", "found", "verify", "confirm", "check", "mention", "understand", "noted",
              "revealed", "discovered", "indicate", "indicates", "determines", "prove",
              "explains", "announced", "observed", "remember", "test", "reveals", "estimate"}
OF_TERMS = {"terms", "term"}
OF_NOUNS = {"years", "months", "ways", "way", "place", "front", "levels", "thousands",
            "millions", "hundreds", "style", "economy", "population", "future"}
TO_VERBS = {"decided", "decide", "decides", "agreed", "failed", "known", "said", "appears",
            "shown", "reported", "failure", "decision", "failing"}
TO_GOOD = {"go", "goes", "enough", "ready", "time", "come"}


def step(carry, prefix, upstream):
    words = [s.strip().lower() for s in prefix.token_strings[-2:]]
    if len(words) < 2:
        return None, 0.0
    prev, cur = words
    if cur == "that":
        if prev in RESULT_WORDS:
            return None, 2.1
        if prev in SUCH_WORDS:
            return None, 1.2
        if prev in SUPPOSE_WORDS:
            return None, 0.45
        if prev in FIND_WORDS:
            return None, -0.15
        return None, 0.05
    if cur == "of":
        if prev in OF_TERMS:
            return None, 0.75
        if prev in OF_NOUNS:
            return None, 0.2
        return None, 0.0
    if cur == "to":
        if prev in TO_VERBS:
            return None, -0.55
        if prev in TO_GOOD:
            return None, 0.2
        return None, 0.0
    if prev in RESULT_WORDS:
        return None, 0.1
    return None, 0.0

