"""Emit fixed guesses for a few connective-word contexts.

Use up to two preceding words from the last five token strings in the current
document to recognize 'that' after 'so' or 'such', the pattern 'so X that',
and a few other cues. Also match selected 'of', 'to', 'as', Russian 'что',
and 'So' contexts. Everything else is zero; this is a lexical heuristic,
not a general grammar parser.
"""

import re

READS = ()

FUNCTION_WORDS = {
    "a", "an", "the", "this", "that", "these", "those",
    "he", "she", "it", "they", "we", "you", "i", "who",
    "is", "are", "was", "were", "be", "been", "being",
    "do", "does", "did", "have", "has", "had", "can", "could",
    "will", "would", "should", "may", "might", "must",
    "and", "or", "but", "if", "as", "to", "of", "in", "on",
    "at", "by", "for", "from", "with", "not", "no", "very",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    first = max(0, prefix.position - 5)
    while first < prefix.position and prefix.document_ids[first] != prefix.document_ids[-1]:
        first += 1
    context = "".join(prefix.token_strings[first:prefix.position]).lower()

    words = []
    for _ in range(2):
        match = re.search(r"([^\W\d_]+)[,;:!?\"'’)}\]]*\s*$", context)
        if not match:
            break
        words.append(match.group(1))
        context = context[:match.start()]
    previous = words[0] if words else ""
    before_previous = words[1] if len(words) > 1 else ""

    if token.lower() == " that":
        if previous == "so":
            return None, 1.8
        if previous == "such":
            return None, 1.25
        if previous == "treating":
            return None, 0.58
        if previous in {"now", "suppose"}:
            return None, 0.65
        if previous in {"enough", "way", "thus", "were"}:
            return None, 0.45
        if before_previous == "so" and previous not in FUNCTION_WORDS:
            return None, 0.9

    if token.lower() == " of":
        if previous == "terms":
            return None, 0.95
        if previous in {"place", "times", "years", "inclusion"}:
            return None, 0.44

    if token.lower() == " to" and previous in {"known", "decision", "decided"}:
        return None, -0.65
    if token.lower() == " as" and previous == "so":
        return None, 0.42
    if token == " что" and previous == "так":
        return None, 0.5
    if token == "So":
        return None, 0.45

    return None, 0.0

