"""Typographic punctuation with a fading novelty boost.

Curly apostrophes and quotes receive the largest response; other non-ASCII
punctuation and unusual spacing receive smaller ones. Earlier typographic
marks damp the response, and their influence fades over about 200 tokens.
Quotes fused with punctuation or newlines receive different strengths.
Ordinary text gets zero, with small exceptions for two chat markers.
"""
import math
import unicodedata

READS = ()
MARKS = frozenset('’‘“”„–—…«»「」『』《》（）！？：；')


def response(text):
    """Return the resting response and the extra response to novelty."""
    s = text.strip()
    if any(c in s for c in '’‘'):
        rest, boost = 0.25, 3.5
        if any(c in s for c in ',.!?'):
            rest, boost = -0.1, 2.3
        elif s in {'’d', '’ll'}:
            rest, boost = -0.1, 3.5
    elif '„' in s:
        rest, boost = 1.35, 0.0
    elif any(c in s for c in '“”'):
        rest, boost = 0.5, 2.3
        if '\n' in text:
            rest, boost = 0.0, 1.4
        elif any(c in s for c in ',，。.?!？！:：、()'):
            rest, boost = 0.2, 1.6
        elif any(c.isalpha() for c in s):
            rest, boost = 0.0, 2.6
    elif '–' in s:
        rest, boost = (0.15, 1.4) if text.startswith(' ') else (0.2, 0.95)
    elif '—' in s:
        rest, boost = (-0.1, 0.7) if text.startswith(' ') else (0.3, 0.4)
    elif '…' in s:
        rest, boost = 0.5, 0.75
    elif any(c in s for c in '«»'):
        rest, boost = 0.6, 0.3
    elif any(c in s for c in '」』》'):
        rest, boost = 0.8, 0.25
    elif any(c in s for c in '「『'):
        rest, boost = 0.3, 0.2
    elif '（' in s:
        rest, boost = 1.0, 0.5
    elif any(c in s for c in '！？：；）【】［］'):
        rest, boost = 0.45, 0.0
    elif any(unicodedata.east_asian_width(c) == 'F' and c != '，' for c in s):
        rest, boost = 0.4, 0.0
    elif any(c in s for c in '′″‴'):
        rest, boost = 0.85, 0.0
    elif '‐' in s:
        rest, boost = 0.65, 0.0
    elif any(c in s for c in '•▪◦'):
        rest, boost = 0.23, 0.0
    elif text == '\r':
        return 0.45, 0.0
    elif len(text) >= 3 and set(text) == {'\xa0'}:
        return min(0.55, 0.1 + 0.07 * len(text)), 0.0
    elif s == '</think>':
        return 0.81, 0.0
    elif s == '<|im_start|>':
        return 0.19, 0.0
    else:
        return 0.0, 0.0
    if '\n' in text and not any(c in s for c in '“”„'):
        rest *= 0.55
        boost *= 0.55
    return rest, boost


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    count = carry[1] if carry is not None and carry[0] == doc else 0
    text = prefix.token_strings[-1]
    rest, boost = response(text)
    value = max(0.0, rest + boost / math.sqrt(1 + count))
    count = (count + sum(c in MARKS for c in text)) * 0.995
    return (doc, count), float(value)

