"""Recognize lo-like spelling fragments, greetings, and 'let' invitations.

Isolated lo is strongest, with different strengths for Lo, LO, and a word
boundary. Attached ello/illo endings are also strong. Other short lo
fragments, a few lo-word families, and greetings give smaller positives.
'Let me' and 'let's' fire on their second token. Everything else gets zero:
this approximates the strong lexical responses, not the diffuse background.
Only the previous token is carried, resetting at each new document.
"""
READS = ()

GREETINGS = {
    'hey': 0.6, 'hola': 1.1, 'bonjour': 1.1, 'goodbye': 1.1,
    'greeting': 1.1, '你好': 2.5, '您好': 1.3, '嗨': 1.3,
}
LO_FRAGMENTS = {'lob', 'loc', 'loe', 'lop', 'los', 'lov', 'lox', 'loo'}
LO_CODAS = {'lore', 'lope', 'lops', 'loon', 'loin', 'loid', 'glob', 'glow'}
OTHER_LO_SCRIPTS = {'ло', 'ło', 'ロ', 'لو'}


def lexical(token, previous, at_start):
    text = token.strip()
    word = text.casefold()
    spaced = token[:1].isspace()
    if word == 'hello':
        if text == 'Hello':
            return 4.2 if spaced else 4.5
        return 3.6 if spaced else 3.3
    if word == 'hi':
        return 1.4 if text == 'Hi' else 0.8
    if word == 'greetings':
        return 1.9 if text[:1].isupper() else 0.9
    if word in GREETINGS:
        return GREETINGS[word]

    syllable = text.lstrip('._-(>')
    if syllable.casefold() == 'lo':
        if syllable == 'Lo':
            return 5.7
        if syllable == 'LO':
            return 4.3 if spaced else 4.0
        if word != 'lo':
            return 5.0
        if spaced or at_start:
            return 4.8
        return 5.4 if not previous[-1:].isalpha() else 4.1
    if word in ('ello', 'illo'):
        return 1.8 if spaced else (4.4 if word == 'ello' else 3.4)
    if word.endswith('lo'):
        if len(word) == 3:
            if word[0] == 'g':
                return 3.1
            if word[0] in 'cux':
                return 0.7
            return 1.4 if word[0] == 'o' else 2.1
        return 2.5 if len(word) == 4 and word.endswith('llo') else 0.7
    if word in LO_FRAGMENTS:
        return 0.8 if word == 'los' else 1.0
    if word == 'loos':
        return 2.0
    if word in LO_CODAS or word.startswith(('loan', 'loot', 'loose', 'slope', 'alloc')):
        return 0.8
    if word in ('loved', 'loves', 'loops'):
        return 0.9 if word == 'loops' else 0.55
    if word in ('love', 'loss', 'lost', 'loop'):
        return 0.25
    if word in OTHER_LO_SCRIPTS or word.endswith('ело'):
        return 1.0
    if word == '洛':
        return 2.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    at_start = carry is None or carry[0] != doc
    previous = '' if at_start else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().casefold()
    value = lexical(token, previous, at_start)
    if previous.strip().casefold() == 'let':
        if word == 'me':
            value += 0.76
        elif word in ("'s", '’s'):
            value += 1.02
    return (doc, token), float(value)

