"""A short lowercase word-beginning signal, strongest after a split capitalized word.

The main response requires a leading space and lowercase ASCII letters.
European conjunctions and isolated letters respond more than English function
words or longer tokens. We keep the preceding alphabetic run (up to 80 trailing
characters) and its number of tokenizer pieces. Capitalized, multi-piece ASCII
runs boost the response, while arithmetic operators suppress it. The calibrated
rates below belong to word classes, not token IDs.
Three explicit chat delimiters also have fixed responses.
"""
import re
READS = ()
ENGLISH_FUNCTION = frozenset('''the a an and or but for nor yet so as at by from in
into of off on out over per to up via with is are am was were be been being do
does did have has had can could may might must will would shall should not no yes
if then than when while where here there that this these those it its I me my mine
you your yours he him his she her hers we us our ours they them their theirs all
any each every few many more most some such who whom what which whose how why only
even also very just too ever never always once twice again much little enough same
other both either neither one two three four five six seven eight nine ten'''.split())
FOREIGN_AND = frozenset('y i et und och og ve'.split())
EUROPEAN_FUNCTION = frozenset('''la le les der die das den dem des un una une ein eine
est ist es son sono se si non ne que qu qui di de du da del dei degli do dos das um
uma io tu noi voi eg jeg het'''.split())


def token_rates(s):
    """Baseline and sensitivity to the preceding word boundary."""
    w = s.strip()
    if not (s.startswith(' ') and w.isascii() and w.isalpha() and w.islower()):
        return (-0.004, 0)
    if w in ('e', 'ed'):  # Portuguese/Italian conjunctions
        return (0.225, 1.12)
    if w in FOREIGN_AND:
        return (0.11, 0.865)
    if w in ('o', 'u'):  # Other isolated lowercase vowels
        return (0.164, 0.816)
    if w == 'a':
        return (-0.009, 0.496)
    if w in ('x', 'q', 'z'):  # Rare letters; often symbolic identifiers
        return (0.002, 0.485)
    if len(w) == 1:
        return (0.054, 0.963)
    if w in ENGLISH_FUNCTION:
        return (-0.004, 0.034)
    if w in EUROPEAN_FUNCTION:
        return (-0.024, 0.326)
    if len(w) == 2:
        return (0.023, 0.539)
    if len(w) == 3:
        return (-0.013, 0.292)
    return (-0.004, 0)


def boundary_strength(s, word, chunks):
    """Capitalization and splitting strengthen an alphabetic word ending."""
    if word:
        if not word.isascii():
            return 0.086
        if chunks > 1:
            return .435 if word[0].isupper() else .257
        if word in ENGLISH_FUNCTION:
            return -0.005
        return .181 if word[0].isupper() else .066
    w = s.strip()
    if not w:
        return -0.086
    if all(c in '=+-*/^<>|&\\' for c in w):
        return -0.122
    if w[-1:].isdigit():
        return 0.032
    return -0.023


def update_word(word, chunks, s):
    if s.isalpha():
        # Bound memory, retaining the end of an alphabetic run.
        return (word + s)[-80:], chunks + 1
    tail = re.search(r'[^\W\d_]+$', s)
    return (tail.group(), 1) if tail else ('', 0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, word, pieces = '', '', 0
    else:
        _, previous, word, pieces = carry
    s = prefix.token_strings[-1]
    baseline, gain = token_rates(s)
    value = baseline + gain * boundary_strength(previous, word, pieces)
    if s == '<tool_call>':
        value = .323
    elif s == '<tool_response>':
        value = .160
    elif s == '<think>':
        value = -.220
    word, pieces = update_word(word, pieces, s)
    return (doc, s, word, pieces), float(value)

