        return .55 * chinese_having(s[:-1])
    if s in POSSESSION:
        return 3.4
    if s in {'有效', '有限', '有时', '有時', '有一天', '有助于', '有利于'}:
        return 1.9
    if s in {'有些', '有点', '有點', '有关', '有關', '有序'}:
        return 3.0
    if s in {'有一', '有所', '有着', '有多'}:
        return 5.1
    if s.startswith('有'):
        return 4.3 if len(s) == 2 else 3.5 if len(s) == 3 else 2.8
    if s.endswith('有'):
