        return HAVE[w] + (.65 if s.startswith('.') else .4 if s.startswith('_') else 0)
    if w in {'tohave', 'hasattr'} or re.fullmatch(r'\.has[A-Z].*', s):
        return 1.8
    if w in {'owned', 'existing'}:
        return 1.6 if s.startswith('-') else 1.2
    if w in {'possess', 'possessed', 'possesses', 'possessing'}:
        return .9
    if w in {'existence', 'presence'}:
        return .65
    if w in {'exist', 'exists', 'existed'}:
        return .27
    if w in PROPERTIES:
        return PROPERTIES[w]
    if '有' in s:
        return chinese_having(s)
    if s in {'无', '無', '毫无', '毫無'}:
        return 1.85
    if s in {'没', '沒', '友', '由'}:  # Absence; also similar-sounding 友 and 由.
        return .95
    if s in {'又', '存在', '具备', '具備', '充满', '充滿'}:
        return 1.3
    if s in {'是', '为', '為', '具', '存', '带', '帶'}:
        return .65
    if s in {'に', 'には', 'にも'}:  # Japanese location particle.
        return .93 if s == 'に' else 1.53
    if s in {'ある', 'あり', 'あります', 'があります', 'にある'}:  # Exist/have.
        return 2.3
    if re.fullmatch('[がにもはの](ある|あり|あります)(が|ので|ました)?', s):
        return 1.8
    if s.endswith(('ている', 'ています')) or s in {'いる', 'います', 'いました'}:
        return .7
