"""A spelling-sensitive lexical response, especially to 'data' and 'high'.

Selected modifiers and noun words have weaker positive responses. Single
Chinese characters get a positive default, except listed function and degree
characters. Chat delimiters and document starts have separate predictions.
These are selected spellings, not a claim that all synonyms behave alike.
"""
READS = ()

STRONG_MODIFIERS = frozenset("next special extra international".split())
MODIFIERS = frozenset("""
    current last original various free open low social personal national
    heavy strong economic military
""".split())
SMALL_MODIFIERS = frozenset("new old large small".split())
HAN_FUNCTION_AND_DEGREE = frozenset(
    "的一是在了有和与與及或而也都不没無无為为被把由到从從对對"
    "这這那它他她你我们們可會会能要将將所者个個其之得地着著"
    "过過还還来來去出上中下内內里外前后後多大小好很更最少第全"
)
CHAT_MARKERS = {
    "<|im_end|>": -0.061,
    "<|endoftext|>": 0.021,
    "<tool_response>": -0.129,
    "</tool_response>": -0.129,
    "<tool_call>": -0.031,
    "</tool_call>": 0.13,
    "<think>": -0.079,
}


def lexical_value(raw):
    word = raw.strip()
    name = word.lstrip("_./($-@")
    lower = name.lower()
    if lower == "data":
        if word.startswith((".", "/")):
            return 0.82
        if word.startswith(("(", "$", "-")):
            return 0.59
        if word.startswith("_"):
            return 0.67
        if raw[:1].isspace():
            return 0.71
        return 0.89 if name == "Data" else 0.77
    if lower == "high":
        return 0.81 if name == "High" and raw.startswith(" ") else 0.64
    if lower in ("higher", "highest"):
        return 0.25
    if lower == "series":
        return 0.56 if name == "Series" else 0.42
    if name == "New":
        return 0.20
    if lower in STRONG_MODIFIERS:
        return 0.25
    if lower in MODIFIERS:
        return 0.17
    if lower in SMALL_MODIFIERS:
        return 0.09
    if lower in ("health", "disease"):
        return 0.20
    if lower in ("king", "queen", "prince", "princess", "royal"):
        return 0.23
    if lower in ("football", "basketball", "soccer"):
        return 0.15
    if word in ("数据", "系列", "データ"):
        return 0.55
    if len(word) == 1 and "\u4e00" <= word <= "\u9fff":
        if word in HAN_FUNCTION_AND_DEGREE:
            return -0.025
        return 0.10
    return 0.0


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip()
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    if word == "<|im_start|>":
        value = -0.288 if first else 0.037
    elif word in CHAT_MARKERS:
        value = CHAT_MARKERS[word]
    else:
        value = lexical_value(raw)
        if first:
            value -= 0.04
    return None, value

