"""A small cue for negative activations: a common auxiliary or linking verb
immediately after a subject-like word. All other positions get zero."""
READS: tuple[str, ...] = ()

AUXILIARIES = frozenset({
    "am", "'m", "is", "'s", "are", "'re", "was", "were", "be", "being",
    "been", "have", "has", "had", "'ve", "'d", "do", "does", "did",
    "can", "could", "may", "might", "must", "shall", "should", "will",
    "would", "need", "needs", "got", "won",
})
SUBJECT_WORDS = frozenset({
    "i", "you", "he", "she", "it", "we", "they", "who", "what",
    "there", "this", "that", "one", "which", "these", "those",
})


def step(carry, prefix, upstream):
    current = prefix.token_strings[-1].strip().lower()
    if len(prefix.token_ids) >= 2:
