programs.sol:
"""Local low-number patterns, especially 22, 23 and 24.

A small decimal-pair table describes strong twenty-something responses,
weaker thirty/forty-something responses, and negative final nines. Numeric
separators weaken this pattern. Fullwidth digits use the same rules.
Document-initial digits have their own response, particularly a strong 2.

English eleven--nineteen, twenty and thirty also respond positively.
In contrast,
phrases like "two different" and "two possible" respond negatively,
as do non-digit endings after 2. Unrecognized text is near zero.
"""
READS = ()

# Columns are the current digit: 0, 1, ..., 9.
DECIMAL_PAIRS = {
    '2': (1.19, 2.08, 3.42, 2.89, 2.01, .70, .16, .10, -.19, -.82),
    '3': (.21, .67, 1.48, 1.37, .99, .32, .00, -.04, -.29, -.61),
    '4': (.20, .27, .52, .61, .52, .15, -.03, -.16, -.23, -.49),
}
FIRST_DIGIT = (.38, .09, 2.91, .95, .30, -.02, -.06, .04, .02, -.05)
OTHER_DIGIT = (.02, .00, .04, .07, .03, -.05, -.07, -.05, -.01, .00)


# A decimal point transmits a weaker version of the same number pattern.
SEPARATORS = {'.': .39, ',': .18, '-': .14, ':': .09, ' ': .26}
TEENS = {
    'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen',
    'sixteen', 'seventeen', 'eighteen', 'nineteen',
}
UNITS = ('zero', 'one', 'two', 'three', 'four', 'five',
         'six', 'seven', 'eight', 'nine')


def plain_digit(token):
    """Treat fullwidth decimal digits as their ordinary printed counterparts."""
    if len(token) == 1 and '\uff10' <= token <= '\uff19':
        return str(ord(token) - ord('\uff10'))
    return token


def step(carry, prefix, upstream):
    token = plain_digit(prefix.token_strings[-1])
    start = (len(prefix.token_ids) == 1
             or prefix.document_ids[-1] != prefix.document_ids[-2])
    previous = '' if start else plain_digit(prefix.token_strings[-2])
    word = token.strip().lower()
    prior_word = previous.strip().lower()
    if len(token) == 1 and token in '0123456789':
        digit = int(token)
        if start:
            return None, float(FIRST_DIGIT[digit])
        if previous in DECIMAL_PAIRS:
            return None, float(DECIMAL_PAIRS[previous][digit])
        value = OTHER_DIGIT[digit]
        if previous in SEPARATORS and len(prefix.token_ids) > 2:
            if prefix.document_ids[-1] == prefix.document_ids[-3]:
                earlier = plain_digit(prefix.token_strings[-3])
                if earlier in DECIMAL_PAIRS:
                    value += SEPARATORS[previous] * (
                        DECIMAL_PAIRS[earlier][digit] - value)
        return None, float(value)
    if word in TEENS:
        return None, .72
    if word in {'twenty', 'thirty'}:
        return None, .95 if word == 'twenty' else .66
    if prior_word in {'twenty', 'thirty'} and word.startswith('-'):
        unit = word[1:]
        if unit in UNITS:
            tens = '2' if prior_word == 'twenty' else '3'
            return None, float(DECIMAL_PAIRS[tens][UNITS.index(unit)])
    # Two-way distinctions have a negative rather than positive response.
    if prior_word in {'two', '2'}:
        scale = 1.0 if prior_word == 'two' else .6
        if word == 'different':
            return None, -2.1 * scale
        if word == 'possible':
            return None, -1.5 * scale
        if word in {'distinct', 'separate', 'identical', 'main',
                    'ways', 'kinds', 'cases', 'methods'}:
            return None, -.95 * scale
        if word in {'other', 'same', 'solutions', 'options', 'sorts'}:
            return None, -.5 * scale
    if previous == '2':
        if token in {'nd', 'th'}:
            return None, -.64  # Ordinal endings: 2nd, 12th, etc.
        if len(token) == 1 and token.isalpha():
            return None, -.28  # Attached letter, as in 2D or 2x.
        return None, -.12
    if previous == '3':
        return None, -.035
    if prior_word == 'two':
        return None, -.10
    return None, -.001

programs.haiku:
"""Second digit of a number that starts with 2 (or 3, 4).

Plain-terms reading: layers.0.mlp.down_proj:2652 is a "2X" number detector. It fires on
the second digit of a number whose first digit is 2: most strongly for 22 and 23, a lot
for 21 and 24, less for 20 and 25, about zero for 26 and 27, and slightly negative for 28
and 29. Numbers that start with 3 give about 0.4 of that, numbers starting with 4 about
0.2. It also fires on a "2" that is the very first token of a document (no context
before it), where it is strongest of all. Every other token is predicted as 0.

The rule reads only the current token, the previous token, and whether a document starts
here, so it keeps no state between positions.
"""

READS = ()

DIGITS = frozenset("0123456789")

# How strongly a number starting with this digit fires on its second digit.
LEAD = {"2": 1.0, "3": 0.4, "4": 0.2}

# How strongly the second digit itself pulls, given the first digit is 2.
SECOND = {"0": 1.2, "1": 2.0, "2": 3.4, "3": 2.9, "4": 2.0, "5": 0.7, "6": 0.15, "8": -0.2, "9": -0.8}

# Activation of a digit that is the first token of a document.
FIRST_IN_DOC = {"2": 2.9, "3": 0.95, "0": 0.4, "4": 0.3}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, float(FIRST_IN_DOC.get(tok, 0.0))
    prev = prefix.token_strings[-2]
    if tok in DIGITS and prev in DIGITS:
        return carry, float(LEAD.get(prev, 0.0) * SECOND.get(tok, 0.0))
    return carry, 0.0

programs.luna:
"""Approximate the component's number-sensitive response to two adjacent digits.

It is strongest on 20–25, weaker on 31–34, and modest on 42–44; other
digit pairs get no response in this simple rule.
"""

READS = ()


def step(carry, prefix, upstream):
    if prefix.position < 1:
        return None, 0.0
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0

    tens, units = prefix.token_strings[-2:]
    if len(tens) != 1 or len(units) != 1:
        return None, 0.0
    if tens not in "0123456789" or units not in "0123456789":
        return None, 0.0

    number = 10 * int(tens) + int(units)
    if 20 <= number <= 25:
        return None, 1.7
    if 31 <= number <= 34:
        return None, 1.15
    if 42 <= number <= 44:
        return None, 0.55
    return None, 0.0

programs.sol:
"""Respond to the spelling 'se', especially at the end of short word pieces.

The letters before 'se', a leading word boundary, capitalization, and simple
inflections change the strength. Common grammar/code words are treated
separately. There is also a small response to isolated 'cd' and Japanese
se / long-vowel s syllables. An acute accent on e is folded away.
'case' is weaker in conditional/discourse phrases (e.g. 'in this case'),
but stronger at a line start, as in a switch statement. Unrecognized tokens
receive nearly zero.
"""
import math

READS = ()
GRAMMAR = frozenset('these those because please diese'.split())
CODE_WORDS = {
    'use': 0.83,
    'case': 0.41,
    'else': 0.53,
    'base': 0.72,
}
# Ending -> (extra response, length before attenuation begins).
SE_ENDINGS = {
    'ose': (1.81, 4),
    'ese': (0.79, 4),
    'ise': (0.23, 4),
    'ase': (0.15, 4),
    'nse': (0.89, 5),
    'rse': (0.55, 5),
    'lse': (1.62, 4),
}


def length_discount(text, short_length=4, rate=0.4):
    """Longer spellings have a weaker response than short pieces."""
    return math.exp(-rate * max(0, len(text) - short_length))


def response(token, previous='', line_start=False):
    raw = token.strip().lstrip('._/-')
    word = raw.lower().replace('é', 'e')
    boundary = token[:1].isspace()
    fragment = not boundary and not raw.istitle()
    if token in {'cd', 'CD'}:
        return 0.49 if token == 'cd' else 0.25
    if raw in {'せ', 'セ'}:
        return 0.61 if raw == 'せ' else 1.03
    if raw.endswith(('ース', 'ーズ')):
        value = 0.98 * length_discount(raw, 3, 0.5)
        return value - (0.28 if raw.endswith('ーズ') else 0.0)
    if not word.isascii() or not word.isalpha() or word in GRAMMAR:
        return -0.002
    if word == 'whose':
        return 0.96
    if word.startswith(('close', 'choose', 'chose')):
        return 0.02
    if word.startswith('sever') and not word.startswith('several'):
        return 1.3 * length_discount(word, 6)
    scale = 1.0
    if len(word) >= 4 and word.endswith(('ses', 'sed')):
        scale = 0.8 if word[-1] == 's' else 0.4
        word = word[:-1]
    if word == 'false':
        return scale * (0.25 if raw.islower() else 0.10)
    if word in CODE_WORDS:
        if word == 'case' and boundary:
            if line_start:
                return scale * 0.73
            if previous in {'in', 'this', 'that', 'any', 'our', 'each'}:
                return scale * 0.10
        if word == 'else' and boundary and line_start:
            return scale * 0.61
        if word == 'base' and scale == 0.4:
            return -0.002
        if word == 'use' and scale == 0.4:
            scale = 0.24
        boost = 0.70 if word == 'use' and raw.islower() else 0.43
        return scale * (CODE_WORDS[word] + boost * (not boundary))
    if word.startswith(('pars', 'arse', 'arsi')):
        value = 1.3 if raw.lower().endswith('se') else 0.72
        return value + (0.32 if word.startswith('ars') else 0.0)
    if word == 'lose':
        return scale * 0.93
    if word.endswith('pose'):
        return scale * length_discount(word)
    if not word.endswith('se'):
        return -0.002
    strength = length_discount(word)
    value = (0.40 + 0.65 * fragment) * strength
    if raw.isupper() and len(word) <= 4:
        value += 0.50 * strength
    for ending, (weight, short_length) in SE_ENDINGS.items():
        if word.endswith(ending):
            value += weight * length_discount(word, short_length)
    if word == 'se':
        value += 0.76
    if word == 'ose' and not boundary:
        value += 0.73
    if word == 'ense' and not boundary:
        value += 0.89
    if word.endswith('ourse'):
        value += 0.97 * length_discount(word, 6, 0.3)
    if word.endswith('verse'):
        value += 0.74 * length_discount(word, 5, 0.3)
    if word.endswith('cose'):
        value -= 0.72 * strength
    return scale * value - 0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', True)
    _, previous, line_start = carry
    token = prefix.token_strings[-1]
    value = response(token, previous, line_start)
    if '\n' in token:
        line_start = not token.rsplit('\n', 1)[-1].strip()
    elif token.strip():
        line_start = False
    if token.strip():
        previous = token.strip().lower()
    return (doc, previous, line_start), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 2653: an "s-e spelling" detector.

It reads the current token's text. It fires when the token ends in the letters s-e
(e.g. "-se", "-ses"):
  - strongly (~1.2) when the token is a piece of a longer word with no leading space,
    e.g. "se" or "ense" inside "sense" or "parse"-like words;
  - moderately (~0.9) when the token is a whole common word from a short list
    (use, case, else, course, base, sense, rose, pose, parse, mice, ...);
  - weakly (~0.3) for any other space-prefixed word ending in -se.
Everything else is near 0. It depends only on the current token's spelling.
"""

READS = ()

# Common whole words in the "s-e" spelling family that the component fires on.
WORDS = {
    "use", "uses", "case", "cases", "else", "base", "mice", "course", "courses",
    "sense", "rose", "pose", "parse", "parser", "lose", "rise", "se",
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    if not (word.endswith("se") or word.endswith("ses")):
        return carry, 0.0
    if not raw.startswith(" "):
        return carry, 1.2  # a fragment inside a longer word
    if word in WORDS:
        return carry, 0.9  # a common whole word from the list
    return carry, 0.3  # any other spaced word ending in -se

programs.sol:
"""Recognize mathematical relations, in symbols, words, and LaTeX.

Order, set membership and approximation give large negative values; equality
is weaker, especially for programming assignments. Greek-letter LaTeX names
and the cursive letter \\ell have a small positive response. Keep 100 characters
of recent context and reset at document boundaries. Unrecognized text stays
near zero. Three UTF-8 byte-prefix tokens also catch mathematical signs
before their final byte arrives.
"""
import re

READS = ()

# Readable mathematical notation, not vocabulary-token identities.
SYMBOLS = {
