import unicodedata

READS = ()
FUNCTION_WORDS = set('a an the and or but of to in on at by for from with as is are '
                     'was were be been being that this these those it its not'.split())
CONTROL_WORDS = set('if for while switch catch return assert elif when'.split())
MATH_COMMANDS = set('sin cos tan cot sec csc sinh cosh tanh sqrt log ln exp '
                     'left right'.split())


def response(s, previous):
    b, prev = s.strip(), previous.strip()
    space = s.startswith(' ')
    word = bool(prev) and prev.isalpha()
    number = bool(prev) and prev.isdigit()
    blank = not prev
    punctuation = bool(prev) and not any(c.isalnum() for c in prev)
    length = min(len(prev), 10) if word else 0
    function = prev.lower() in FUNCTION_WORDS
    control = prev.lower() in CONTROL_WORDS
    math = prev.lower() in MATH_COMMANDS
    if b == 'frac':
        return .96  # LaTeX's fraction command.
    if b == '（':
        return .80
    if len(b) == 1 and b in '《【『〈':
        return .50
    if space and len(b) == 1:
        script = unicodedata.name(b, '').split(' ')[0]
        if script in ('HANGUL', 'CJK', 'HIRAGANA', 'KATAKANA'):
            return .58
    if any(c.isalnum() for c in b):
        return .002
    if b.startswith('('):
        if space:
            if b.startswith('(-'):
                return 1.01
            if b.startswith('()'):
                return 1.06
            if len(b) > 1 and b[1] in "'`/!$@<#_&%;.":
                return 2.15
            return (2.12 - .48*word - .81*number - 1.04*blank
                    - .98*punctuation + .031*length - .25*(function and not control)
                    + .27*control - .46*math
                    + .25*(word and not prev.islower() and not prev.isupper())
                    - .18*(prev in ('=', '+', '-', '/', '*'))
                    + .30*(punctuation and any(c in prev for c in "'\"`")))
        if b == '(':
            return (-.25 + .25*word + .24*number + .73*blank
                    + .77*punctuation - .043*length - .12*function
                    + .35*math + .50*(word and not prev.isascii()))
        if b.startswith('()'):
            return -.005
        if '\n' in s:
            return -.12
        return .42
    if b.startswith('['):
        if space:
            if '\n' in s:
                return .48
            return .88 + .07*word - .14*number - .58*blank - .30*punctuation
        return .05 if b == '[' else .21
    if b.startswith('{'):
        if '\n' in s:
            return .014 if space else -.12
        if space:
            return .65 if len(b) > 1 else (.49 + .12*word - .24*blank
                                          - .09*punctuation)
        return .11
    if b.startswith('__') or b.endswith('__'):
        opening = (b.count('_') == 2 and (b.endswith('__') or b == '__(')
                   and '\n' not in s)
        return (.80 + .35*space) if opening else .34
    if space and b[:1] in ('"', "'", '“', '‘', '`', '«'):
        if b.startswith(('""', "''")):
            return .18
        if len(b) > 1 and b[1] in '/\\$<-+':
            return .24
        if b[0] in "'‘":
            return (.80 + .09*word - .18*number - .44*blank
                    - .14*punctuation + .025*length)
        if b[0] == '`':
            return (.21 + .11*word + .05*number - .34*blank
                    - .14*punctuation + .02*length)
        return (.77 - .07*word - .25*number - .53*blank
                - .31*punctuation + .024*length + .08*function)
    if space and b.startswith('\\"'):
        return .62
    if b.startswith('=') and len(b) > 1 and b[1] in '(\'"[{\\':
        return .50
    if not space and '(' in b and not b.startswith((')', ']', '}')):
        return .42
    if space and b.startswith('<'):
        return (.65 - .32*word - .37*number - .58*blank
                - .28*punctuation + .041*length + .22*function)
    if b == '\\\\':
        return .49
    if space and not b and '\n' in s:
        return .135
    if space and b.startswith('**'):
        return .51
    if b in ('✓', '✔'):
        return .73 if space else .002
    if space and b in ('/', '%', ':', '_', '>', ')', '}', '#'):
        return .14
    return .002


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    return (doc, s), float(response(s, previous))

