PAREN_OPENERS = {" (", " ([", " (\n", " ()"}
QUOTE_OPENERS = {' "', " '", " [", " <", " {", " `", "__", " {\\"}


def after_word(prefix):
    if len(prefix.token_strings) < 2:
        return False
    previous = prefix.token_strings[-2].rstrip()
    return bool(previous) and (previous[-1].isalnum() or previous[-1] == "_")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in PAREN_OPENERS:
        return carry, 1.8 if after_word(prefix) else 1.0
    if token in QUOTE_OPENERS:
        return carry, 0.6
    return carry, 0.0

