        if at == 0:
            value -= 0.35
        else:
            value += PRECEDING_V.get(word[at - 1], 0.0)
        if word.endswith('v'):
            value += 0.39
            if length <= 4:
                value += 0.24
        if word.endswith(('ve', 'ves', 'ved')):
            value += 0.17
        if word.endswith(('ving', 'vings')):
            value += 0.34
        if length <= 4 and word.endswith('ve'):
