            value -= 0.74
        if length == 1:
            value -= 0.30
        if STRONG_V_VERBS.fullmatch(word):
            value += 1.07
        if OTHER_V_VERBS.fullmatch(word):
            value += 0.76
        if word in {'have', 'having', 'haven'}:
            value -= 1.06
        if word in NUMBER_WORDS:
            value -= 0.82
        if word in QUANTIFIERS:
            value -= 0.50
        if length >= 6 and word.endswith(('ive', 'ives', 'ively')):
            value -= 0.38
        if word.endswith(('ative', 'atives')):
            value -= 0.15
        if word.endswith(('vice', 'vices')):
            value -= 0.42
