        elif n == 3:
            value = -0.28
        elif n == 5:
            value = -0.17
        elif n == 7:
            value = -0.07
        elif 8 <= n <= 19:
            value = 0.20
    return position, float(value)

programs.haiku:
"""Indentation-width detector (layer 0, MLP down_proj, component 2659).

The component reads only the current token. It responds to indentation: tokens made of
plain spaces (optionally followed by a newline, or preceded by one tab). Its sign and size
depend on the indent width, counted in spaces:

- Short indents of 3, 5 or 7 spaces push the activation strongly negative (about -0.9,
  -0.7, -0.9). Indents of 4, 6, 9 and 11 spaces are weakly or moderately negative.
- Long indents of 12 to 40 spaces, the even widths especially, are positive (about +0.45).
  A long run of spaces that ends a line (a newline after the spaces) is positive (+0.3).
- A tab followed by three spaces is negative (-0.28). A lone tab is slightly positive.
- A single or double space, and every other token, predict 0.

The program keeps no state: each position is judged from its own token string.
"""

READS = ()

# Typical activation for a run of spaces only, by its width in spaces.
WIDTH_RESPONSE = {3: -0.9, 4: -0.15, 5: -0.7, 6: -0.35, 7: -0.9, 9: -0.33, 11: -0.4}
DEEP_INDENT = 0.45  # 12 to 40 spaces, even width
DEEP_LINE_END = 0.3  # 12 or more spaces then a newline


def spaces_only(text):
    return len(text) > 0 and set(text) == {" "}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = 0.0
    if spaces_only(token):
        width = len(token)
        if width in WIDTH_RESPONSE:
            value = WIDTH_RESPONSE[width]
        elif 12 <= width <= 40 and width % 2 == 0:
            value = DEEP_INDENT
    elif token.endswith("\n") and spaces_only(token[:-1]) and len(token) - 1 >= 12:
        value = DEEP_LINE_END
    elif token.startswith("\t") and spaces_only(token[1:]):
        value = -0.28 if len(token) == 4 else 0.0
    elif token == "\t":
        value = 0.06
    return carry, float(value)

programs.luna:
"""Assign negative scores to a few whitespace-only token chunks.

High-importance examples are concentrated on space runs, especially the
three-space token. The other observed chunks receive smaller estimates;
all nonmatching tokens receive zero.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "   ":
        return None, -0.97
    if token == "       ":
        return None, -0.94
    if token == "     ":
        return None, -0.63
    if token == "           ":
        return None, -0.46
    if token == "\t   ":
        return None, -0.26
    return None, 0.0

programs.sol:
"""Detect periods and related separators immediately after a number.

The main response is to a standalone ASCII period: decimal points, version
separators, and list-item numbers all qualify. Its strength varies with the
last digit, preceding punctuation density, and distance from document start.
Joined periods (e.g. period-newline) respond less. Chinese and Roman numeral
boundaries are included; ordinary words and punctuation are mostly quiet.
"""
import math
import re

READS = ()
CHINESE_NUMERALS = frozenset('一二三四五六七八九十')


def numeric_period(before_text, last_digit, position):
    """Stronger in short, punctuation-rich contexts and after a zero."""
    before = before_text[-1:]
    value = 2.25 - 0.133 * math.log1p(position)
    value += 0.22 * (last_digit == '0')
    value += 0.48 * bool(before and before in '([{')
    punctuation = sum(c in '.,_/{(["\'' for c in before_text[-40:])
    return value + 0.037 * punctuation


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, previous, position = '', '', 0
    else:
        _, text, previous, position = carry
    token = prefix.token_strings[-1]
    last = text[-1:]
    ascii_digit = bool(last) and last in '0123456789'
    value = 0.0

    if token == '.':
        value = 0.01
        if ascii_digit:
            value = numeric_period(text.rstrip('0123456789'), last, position)
        elif last and last.isdecimal():
            value = 1.9
        elif last and last.isdigit():
            value = 0.50  # Superscript and subscript numerals.
        elif previous.strip() and re.fullmatch('[IVX]+', previous.strip()):
            value = 0.30 if len(previous.strip()) == 1 else 0.80
    elif token.startswith('.') and ascii_digit:
        suffix = token[1:]
        if '\n' in suffix or suffix.isspace():
            value = 0.19
        elif suffix[0].islower():
            value = 0.10
        elif suffix[0].isupper():
            value = 0.45
        else:
            value = 0.50
    elif token == ' .' and ascii_digit:
        value = 0.46
    elif token == '．' and last and last.isdecimal():
        value = 1.20
    elif token == '、':
        if previous in CHINESE_NUMERALS and previous:
            value = 2.2 + 0.45 * (previous == '一')
        elif ascii_digit:
            value = 0.43
    elif token in (')', '）') and previous in CHINESE_NUMERALS and previous:
        value = 1.50

    return (doc, (text + token)[-64:], token, position + 1), float(value)

programs.haiku:
"""A full stop right after a number fires: '1.5', '10.', 'Question 2.' (about 1.8).
Weaker responses: a full stop after a Roman numeral ('II.', about 1.0), a space-
separated ' .' after a digit (about 0.5), and a full stop glued to a following word
('2.F', about 0.3)."""
READS: tuple[str, ...] = ()
DIGITS = set("0123456789")
ROMAN = set("I II III IV V VI VII VIII IX X".split())


def step(carry, prefix, upstream):
    s = prefix.token_strings
    if len(s) < 2:
        return carry, 0.0
    now, before = s[-1], s[-2]
    if now == ".":
        if before in DIGITS:
            return carry, 1.8
        if before in ROMAN:
            return carry, 1.0
        return carry, 0.0
    if now == " ." and before in DIGITS:
        return carry, 0.5
    if before in DIGITS and now.startswith(".") and len(now) > 1:
        return carry, 0.3
    return carry, 0.0

programs.sol:
"""Approximate a response to Python declarations, blocks, and imports.

Definition-ending colons are strongly positive; other suite colons are
weaker. Declaration words and selected operators are negative. Import
syntax is positive, especially NumPy/Pandas aliases. Most other tokens
predict zero. Document-initial Title labels have a separate response.
A line buffer and fading Python evidence supply context;
new documents reset both. These are syntax heuristics, not a full parser.
"""
import re

READS = ()
NUMERICAL_PACKAGES = {'numpy', 'pandas'}
LEADER = r'^\s*(?:\d+\s*)?[+\-#`]*\s*(?:async\s+)?'
START = re.compile(LEADER + '$')
SUITE = re.compile(
    LEADER + r'(if|elif|else|for|while|with|try|except|finally)\b'
)
FUNCTION = re.compile(r'\bdef\s+\w+\s*\(')

# Strengths for: colon alone, newline, blank line, escaped newline.
COLONS = {
    'function': (1.9, 4.5, 3.5, 1.9),
    'class': (1.0, 3.6, 2.5, 1.8),
    'suite': (1.1, 2.6, 1.6, 1.3),
    'closed': (0.65, 1.8, 0.8, 1.8),
    'plain': (-0.01, 0.28, 0.05, 0.4),
}
KEYWORDS = {
    'if': (-0.05, -0.3), 'elif': (-0.3, -0.5),
    'else': (-0.3, -1.1), 'try': (-0.1, -0.4),
}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, '', 0.0, 0, False)
    _, before, evidence, age, block = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    line = (before + token)[-1500:]
    start = bool(START.fullmatch(before))
    depth = sum(line.count(c) for c in '([')
    depth -= sum(line.count(c) for c in ')]')

    evidence *= 0.995
    if FUNCTION.search(line) or re.search(
        r'\bfrom\s+[\w.]+\s+import|\bself\.', line
    ):
        evidence = 1.0
    if ';' in token or '{' in token:
        evidence *= 0.2
    if '\n' in token and re.search(
        r'\bimport\s+[a-z_][\w.]+(?:\s+as\s+\w+)?\s*$', line
    ):
        evidence = max(evidence, 0.7)
    if '"""' in token or "'''" in token:
        evidence = max(evidence, 0.7)
    python = evidence > 0.35
    value = 0.0

    head, colon, tail = token.partition(':')
    is_colon = (
        colon and not any(c.isalnum() for c in head)
        and all(c in '\\nr\n\r\t ' for c in tail)
    )
    if is_colon:
        ending = 2 if tail.count('\n') > 1 else 1 if '\n' in tail else 0
        if '\\' in tail and '\n' not in tail:
            ending = 3
        kind = 'closed' if any(c in head for c in ')]') else 'plain'
        if depth <= 0:
            if FUNCTION.search(line):
                kind = 'function'
            elif re.search(r'\bclass\s+\w+', line) and '{' not in line:
                kind = 'class'
            elif SUITE.match(line):
                kind = 'suite'
        value = COLONS[kind][ending]
        if kind in ('function', 'class') and ending == 1 and age < 30:
            value += 0.8
        if kind == 'closed' and ending == 0 and any(c in head for c in "('\""):
            value += 0.65
        if kind == 'plain' and "'" in head:
            value = (0.2, 1.7, 0.7, 0.7)[ending]
        elif kind == 'plain' and '"' in head:
            value = (0.0, 1.2, 0.6, 0.5)[ending]
        if '__main__' in line and '__name__' in line:
            value = (0.6, 4.6, 1.0, 1.3)[ending]
            if ending == 1:
                value = 6.0 if '__"' in head else 3.8
        if before.rstrip().endswith(('Title', 'title')) and ending == 0:
            value = -0.2
            if age < 8:
                value = -1.13 if before.rstrip() == 'Title' else -0.56
        block = kind in ('function', 'class', 'suite') and ending != 0
        if block and ending in (1, 2):
            evidence = max(evidence, 0.7)
    elif word == 'Title' and age == 0:
        value = 1.24
    elif word == 'class':
        if before.endswith('__'):
            value = -3.75
        elif age == 0 and token == word:
            value = -4.66
        elif start:
            value = -4.7 if python else -1.25
            if token != word:
                value = -2.1 if python else -0.95
        else:
            value = -2.4 if python else -0.7
            if token != word:
                value = -1.4 if python else -0.2
    elif word == 'def' and start:
        value = -0.22 if token == word else -0.38
    elif word == 'from' and start:
        value = -0.7 if token == word else -0.45
    elif word == 'import':
        module = re.search(r'\bfrom\s+([\w.]+)\s*$', before)
        if module:
            value = 0.85 if '.' in module[1] else 1.2
        elif python:
            value = 0.35
        elif start and token == word:
            value = 0.05
    elif word == 'as' and token != word:
        module = re.search(r'\bimport\s+([\w.]+)\s*$', before)
        if module:
            value = 2.0 if '.' in module[1] else 1.2
            if module[1] in NUMERICAL_PACKAGES:
                value = 2.85
        elif re.search(r'\b(?:numpy|pandas)\s*$', before):
            value = 2.5
    elif word in KEYWORDS and start:
        value = KEYWORDS[word][int(python)]
    elif word in ('==', '!=', '+=', '//'):
        value = -0.5 if python else -0.05 if word == '==' else -0.15
    elif word in ('int', 'bool', 'float', 'str', 'list', 'super'):
        value = -0.25 if python else -0.05
        if word == 'super':
            value = -1.7 if python else -0.17
    elif '{' in token and '\n' in token:
        value = -0.2 if python or re.search(r'\belse\s*$', before) else -0.02
        if re.search(r'\bclass\s+\w+', before):
            value = -0.13
    elif token.isspace():
        if '\n' in token and re.search(r'\bimport\s+[\w.]+', before):
            value = 0.25 if token.count('\n') > 1 else 0.55
        elif '\n' not in token and len(token) >= 3 and start and python:
            value = 0.5 if block else 0.2
    elif ('"""' in token or "'''" in token) and '\n' in token:
        value = 0.5
    elif word == '/python':
        value = 0.65
    elif word == '.py':
        value = 0.1
    elif word == ':-':
        value = 0.85

    if not is_colon and token.strip():
        block = False
    if token.isspace() and '\n' not in token:
        block = False
    escaped = re.search(r'\\+[nr]', line[max(0, len(before) - 4):])
    if '\n' in token or escaped:
        if FUNCTION.search(line) and depth > 0:
            line = re.sub(r'\\+[nr]', '\n', line)
        else:
            line = re.split(r'\r?\n|\\+[nr]', line)[-1]
    return (document, line, evidence, age + 1, block), float(value)

programs.luna:
"""Approximate the component's response to line-ending punctuation: especially
Python function signatures, more weakly other colon-ended lines, and negatively
an opening brace before a newline. Other tokens default to zero."""

READS = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous_line = (
        carry[1] if carry is not None and carry[0] == document else ""
    )
    token = prefix.token_strings[-1]
    line = previous_line + token
    value = 0.0

    if "\n" in token or "\r" in token:
        before_break = line.split("\n", 1)[0].split("\r", 1)[0].rstrip()
        if before_break.endswith(("):", "]:", "}:", ":")):
            if before_break.lstrip().startswith(("def ", "async def ")):
                value = 4.0
            elif before_break.endswith("):"):
                value = 0.85
            else:
                value = 0.45
        elif before_break.endswith("{"):
            value = -0.6
    elif token.rstrip().endswith("):"):
        value = 0.65

    if "\n" in line or "\r" in line:
        tail = line.rsplit("\n", 1)[-1].rsplit("\r", 1)[-1]
    else:
        tail = line

    return (document, tail), float(value)

programs.sol:
"""A partial local spelling-boundary approximation, not a full reconstruction.
Joined continuations after n are negative on average, and those after f
positive. Single letters, grammatical endings, word boundaries and capital
initials change that baseline. Cyrillic н, Arabic ن and Thai น are treated
as n as well. Small responses for markup, selected English word classes,
whitespace and underscore delimiters supplement the spelling rules.
These are class averages: rare fragment-specific spikes are not reproduced.
"""
READS = ()
N_LETTERS = frozenset('nнنน')
ENDINGS = frozenset('s es ed ing er est ly ion ions al ity ic ous ive '
                    'ness ment ent ant ance ence able ible en ist ism '
                    'ine ate ary ory ial ally or ee ize ise'.split())
MARKUP = {'<think>': 0.1504, '</think>': 0.2453,
          '<tool_response>': 0.0983,
          '</tool_response>': 0.0807,
          '<|im_start|>': 0.0131, '<|im_end|>': -0.0401}
# Lexical classes are deliberately small, not a vocabulary lookup table.
WORD_CLASSES = (
    (frozenset('high higher highest low lower lowest'.split()), -0.0759),
    (frozenset('they them their'.split()), 0.0298),
    (frozenset('someone anyone everyone'.split()), 0.0562),
    (frozenset('much rather very too'.split()), 0.0591),
    (frozenset('himself itself'.split()), -0.0637),
)


def activation(token, previous):
    if token in MARKUP:
        return MARKUP[token]
    if token.isspace():
        return -0.0048
    if len(token) >= 2 and set(token) == {'_'}:
        return -0.0594
    if token.startswith(' ') and token[1:].isalpha():
        word = token[1:].lower()
        for words, value in WORD_CLASSES:
            if word in words:
                return value
    last = previous[-1:].lower()
    is_n = last in N_LETTERS
    if token.isdigit():
        if is_n:
            return -0.0463
        if last == 'f':
            return 0.0122
    if token.startswith(' ') and token[1:2].isalpha():
        if is_n:
            return 0.0071
        if last == 'f':
            return -0.0057
    if token[:1].isalpha() and previous:
        ending = token.lower() in ENDINGS
        if is_n:
            if len(token) == 1:
                return 0.0249
            if ending:
                return 0.0174
            if last != 'n':
                return -0.0545
            stem = previous.strip()
            if len(stem) == 1:
                if token.istitle():
                    return -0.0092
                return -0.1107 if stem == 'N' else -0.0635
            return -0.0242 if len(stem) == 2 else -0.01
        if last == 'f':
            if ending or len(token) == 1:
                return -0.02
            return 0.0506 if len(token) >= 4 else 0.0142
    return -0.0003


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    return (doc, token), float(activation(token, previous))

"""A line-opening signal, especially for capitalized prose.
After a newline, determiners and pronouns respond most strongly. Other
capitalized words respond less, with lower responses for long words and
acronyms. Lowercase code, numbers, whitespace, and markup are mostly quiet.
Indentation or opening markup attenuates the line-opening response.
The end-of-thought delimiter is a positive special case; closing tags
otherwise have a small negative response.
