import unicodedata

READS = ()
# Closed word classes and familiar ways of introducing a sentence.
OPENERS = (
    (2.09, 'The This'),
    (1.68, 'A An That These Those Some All Another Each Every One'),
    (1.87, 'I We You It There'),
    (1.48, 'He She They'),
    (1.66, 'My Our Your Its Their His Her'),
    (1.71, 'In To For At By With After From On Since Of Into During As'),
    (1.61, 'If But So While When However Although Because Unless'),
    (1.50, 'Now Here Let Please Wait Yes No Not Perhaps'),
    (1.24, 'What How Which Why Who Where Is Are Can Do Does Will'),
    (1.20, 'Alternatively Similarly Therefore Thus First Second Then Also And Or'),
    (0.45, 'References Contents Introduction Conclusion Abstract '
           'Appendix Section Category'),
    (1.63, 'La Le Les El Los Las Die Der Das En'),
    (1.95, 'Hmm Hm Oh'),
)
