        if 'CYRILLIC' in unicodedata.name(s[0], ''):
            return 1.56
        if len(s) == 1:
            return 1.17
        if s.isupper():
            return max(0.15, 0.85 - 0.09 * len(s))
        return 1.27 - 0.07 * min(len(s), 6)
    if s[0].islower():
        return 0.09
    if s[0].isalpha():
        return 0.57
    if s[0].isdigit():
        return -0.07
    if s == '</think>':
        return 0.95
    if s.startswith('</'):
        return -0.25
    if s.startswith('<') and s.endswith('>'):
        return 0.08 if s.startswith('<|') else 0.20
    if s[0] in '\"“‘' or (s[0] == "'" and len(s) > 1):
        return 0.55
