    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        scale, delay = 0.0, 0
    else:
        _, scale, delay = carry
    value = 0.0
    if scale:
        value = scale * line_response(s) * (0.2 ** delay)
    if '\n' in s:
        scale, delay = 0.0, 0
        if s.endswith('\n'):
            before_break = s.rstrip('\r\n')
            scale = 1.0
            if not before_break and s.count('\n') == 2:
                scale = 1.08
            if before_break.endswith((':', '：', ',')) or before_break.isspace():
                scale = 0.88
    elif scale and (not s.strip() or all(c in '*_`\"\'“‘#>- ' for c in s)):
        delay += 1
    else:
        scale = 0.0
    return (doc, scale, delay), float(value)

