VOWEL_L = {'al', 'el', 'il', 'ol', 'ul'}
ACTIVITIES = {
    'produce', 'produced', 'producing', 'creation', 'creations',
    'manufacturing', 'formation', 'calculation', 'calculations',
    'recorded', 'recording', 'recordings', 'development', 'acquisition',
    'contribution', 'contributions', 'cultivation', 'reproduction',
    'experimental', 'educational', 'computation', 'computational',
}
PRODUCTION_TRANSLATIONS = {'生产', '生產', '生产的', '生产线', '出产'}
OTHER_TRANSLATIONS = {
    '制作', '製作', '创作', '創作', '消费', '消費', '教学', '教學',
    'производства', 'производство', 'производстве', '생산', 'producción',
