"""C-shaped letter detector: mostly negative, strongest for separate capitals.

It recognizes Latin C/c and Cyrillic С/с, discounts bare letters continuing
words, and gives weaker responses to short C-final abbreviations or consonant
clusters. Spaces, punctuation, case and document-start position set the size.
It also recognizes compatibility forms of C and Celsius/copyright symbols.
Most other tokens receive zero, omitting small, token-specific responses.
"""
import math
import unicodedata

READS = ()
VOWELS = frozenset('aeiou')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        position, previous = carry[1] + 1, carry[2]
    token = prefix.token_strings[-1]
    letters = ''.join(ch for ch in token if ch.isalpha())
    spaced = token[:1].isspace()
    suffix = token == letters and previous[-1:].isalpha()
    value = 0.0

    if letters == 'C':
        if token == 'C':
            value = -2.36 if suffix else -2.68
        else:
            value = -2.49 if spaced or token[:1] in '-+/' else -2.05
    elif letters == 'c':
        if token == 'c':
            value = -1.53 if suffix else -2.1
        else:
            value = -1.6 if token[:1] in '-/' else -1.94
    elif letters == 'С':
        value = -2.35 if spaced else (-1.9 if suffix else -2.93)
    elif letters == 'с':
        value = -0.76 if suffix else -1.6
    elif '℃' in token or '©' in token:
        value = -1.4 if '℃' in token else -0.7
    elif unicodedata.normalize('NFKC', letters) in ('C', 'c'):
        # Fullwidth, superscript and mathematical C-shaped variants.
        value = -1.8 if letters.isupper() else -1.5
    elif 2 <= len(letters) <= 4 and letters.endswith('C'):
        value = -1.6 if len(letters) == 2 else -0.9
        if letters[-2] in 'AIUN':
            value *= 0.4
        elif letters[-2] in 'EO':
            value *= 0.7
    elif len(letters) == 2 and letters.endswith('c'):
        before = unicodedata.normalize('NFD', letters[0].lower())[0]
        if before in VOWELS:
            value = -0.4 if spaced else -0.1
        else:
            value = -0.3 if before == 'n' else (
                -0.75 if before in 'crs' else -1.6)
    elif 3 <= len(letters) <= 4 and letters.endswith('c'):
        lower = letters.lower()
        if lower.endswith('rc') and (
                len(lower) == 4 or lower[0] in VOWELS):
            value = -0.8
        elif len(lower) == 3 and lower.endswith('sc'):
            value = -0.45
        elif len(lower) == 3 and lower[-2] in 'bdfgjklmpqvwz':
            value = -1.2

    if letters in ('C', 'c', 'С', 'с'):
        value -= 0.6 * math.exp(-position / 8)
        if position == 0 and token in ('C', 'c'):
            value = -4.03 if token == 'C' else -2.86
    return (doc, position, token), value

