programs.haiku:
"""Layer-0 MLP component 2671 (down_proj): a word-onset consonant-cluster detector.

What it does: the component switches strongly negative on a token that is only the
consonant cluster that opens an English word, cut off before any vowel: "br", "bl", "cr", "gr",
"fl", "pr", "tr", "sw", "sh", "sk", "st", "sp", and the digraphs "th", "ch", "ph", "wh", "qu".
These are sub-word fragments of longer words, so the model has to see them continued. Three-letter onsets such as "str", "sch", "spr" are
weaker, because they are often whole tokens in their own right. Every other token gets 0.

Why: the activation is almost a pure function of the current token's spelling, so a list of
onset clusters, grouped by how strongly each one fires, captures most of its variance.
Matches are case-insensitive and ignore a leading space or punctuation ("-br", " Th").
"""

READS = ()

LIQUID_AND_S_ONSETS = {
    "bl", "br", "cl", "cr", "dr", "fl", "fr", "gl", "gr", "pl", "pr", "tr",  # stop/fricative + liquid
    "sc", "sh", "sk", "sl", "sm", "sn", "sp", "st", "sw",  # s + consonant
}
DIGRAPH_ONSETS = {"th", "ch", "ph", "wh", "qu", "tw"}
TRIPLE_ONSETS = {"str", "spr", "scr", "shr", "thr", "sch", "spl", "squ", "sph"}

LIQUID_S_VALUE = -1.3
DIGRAPH_VALUE = -0.9
TRIPLE_VALUE = -0.4
WORD_START_SCALE = 1.2
BARE_SCALE = 0.8


def _core(token: str) -> str:
    """The token's letters, lowercased, without a leading space or punctuation mark."""
    return token.strip().lstrip("-_./(\\\"'").lower()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    core = _core(token)
    if core in LIQUID_AND_S_ONSETS:
        value = LIQUID_S_VALUE
    elif core in DIGRAPH_ONSETS:
        value = DIGRAPH_VALUE
    elif core in TRIPLE_ONSETS:
        value = TRIPLE_VALUE
    else:
        return None, 0.0
    # A word-initial piece (leading space or punctuation) fires a bit harder than a bare
    # letter-run piece, which is usually the middle of a word.
    if token[:1].isalpha():
        value *= BARE_SCALE
    else:
        value *= WORD_START_SCALE
    return None, float(value)

