REPAIR_MARKERS = {"wait", "actually", "alternatively", "rather"}

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word, capped, old_doc = carry if carry is not None else ('', False, doc)
    if doc != old_doc:
        word, capped = '', False
    for ch in prefix.token_strings[-1]:
        if ch.isalpha():
            if not word:
                capped = ch.isupper()
            word += ch
        elif ch.isdigit():
            word += ch
        elif ch in "'-’":
            if word:
                word += ch
            else:
                capped = False
        else:
            word, capped = '', False
    value = 0.02 if capped else 0.0
    if word.casefold() in REPAIR_MARKERS:
        value += 0.15
    return (word[-32:], capped, doc), value

