"""HTML/XML element names, attributes, and a smaller programming-else response.

Names are strongest after '<', weaker after '</', and often weakly active as
identifiers or fragments. Quotes, capitalization, whitespace and document start
also modify the response. Form controls and DOM operations have smaller bumps.
Grouped strengths are approximate; state is recent text, reset per document.
"""
import re

READS = ()

# Names grouped by approximate opening-tag response.
TAG_LEVELS = {
    4.1: 'span div td',
    3.1: 'tr li strong img label option tbody thead textarea fieldset blockquote',
    2.3: 'th button input table body form select small sup svg article section '
         'iframe canvas dd legend figure figcaption kbd',
    1.4: 'a p h ul br hr em code pre script style head html summary details '
         'path circle rect header footer link meta font title nav main param '
         'source embed dt dl col tt video audio center template abbr remarks '
         'typeparam returns see',
    0.8: 'b i u ol sub',
}
TAGS = {name: level for level, names in TAG_LEVELS.items()
        for name in names.split()}
# Residual responses without tag brackets: (bare name, whitespace-led name).
WORD_LEVELS = {
    'span': (1.8, 0.85), 'div': (1.0, 0.65), 'td': (1.1, 1.0),
    'tr': (0.27, 0.29), 'th': (0.11, 0.11), 'li': (0.27, 0.4),
    'strong': (0.5, 0.09), 'img': (1.0, 0.6), 'label': (0.3, 0.26),
    'option': (0.46, 0.2), 'button': (0.6, 0.24), 'input': (0.3, 0.04),
    'body': (0.37, 0.1), 'form': (0.15, 0.0), 'svg': (0.52, 0.64),
    'select': (0.37, 0.1), 'br': (0.16, 0.14),
}
ATTRIBUTES = {
    'href': 1.75, 'colspan': 1.2, 'rowspan': 2.0,
    'cellspacing': 1.8, 'cellpadding': 1.1, 'onclick': 0.7,
    'onClick': 1.25, 'viewBox': 1.2,
}

CONTROLS = {'radio', 'submit', 'click', 'placeholder', 'align', 'aligned'}
DOM_ACTIONS = {'createElement', 'querySelector', 'getElementById',
               'addEventListener', 'preventDefault'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    before = '' if first else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    spaced = token[:1].isspace()
