    closing = bool(re.search(r'<\\?/$', before)) and not spaced
    in_tag = before.rfind('<') > before.rfind('>')
    value = 0.0

    if word == 'else':
        if before.rstrip().endswith('}') or re.search(r'\n[ \t]+$', before):
            value = 0.67
        elif token == 'else' or token.startswith('\t'):
            value = 0.47
        elif re.search(r'(some|any|every|no)(thing|one|body|where)\s*$', before):
            value = 0.1
        else:
            value = 0.3
    elif low in TAGS:
        level = TAGS[low]
        bare, space = WORD_LEVELS.get(low, (0.04, 0.0))
        if closing:
            value = 0.6 * level
        elif opening:
            value = level
        elif word.startswith('<'):
            value = 0.9 * level
            if low == 'img':
                value = 1.8
        elif before.endswith(('"', "'")) and not spaced:
            value = bare + 0.15
            if low in ('span', 'div', 'td', 'li', 'img', 'button',
                       'input', 'form', 'label'):
                value = max(value, 0.65 * level)
            if 'createElement' in before[-70:]:
                value = level
        else:
            value = space if spaced else bare
            if word[:1] in './(:;_':
                value *= 0.65
        if first and len(low) > 1 and name == low:
            factor = 0.8 if low in ('span', 'div', 'td', 'li') else 0.5
            value = max(value, (0.4 if spaced else factor) * level)
        if name != low:
            value *= 0.4
        if word.startswith('.') and before.endswith('styled'):
            value = 0.8 * level
