        value = ATTRIBUTES[name]
        if name == 'href' and not spaced:
            value = 1.0
    if name in CONTROLS:
        value = 0.1 if spaced else 0.45
    elif name == 'checkbox':
        value = 0.7 if spaced else 1.5
    elif name in DOM_ACTIONS:
