"""layers.0.mlp.down_proj:2675 — HTML element names in markup, plus code 'else'.

What it does: this component reads the token at each position and fires when the token
is an HTML element name that opens or closes a tag, i.e. it comes right after '<' or '</'
(as in "<td>", "</div>", "<tr"). Opening tags fire harder than closing ones, and the
most common layout tags (td, span, div, tr, img) hardest. Attribute names that carry
a table or link meaning (href, onclick, colspan, rowspan) fire moderately. A bare
'div', 'span', 'td' or 'img' outside a tag fires weakly. The keyword 'else' fires as
a code keyword (after '}' or at the start of an indented line), but not in prose
("something else").

The levels are rounded least-squares fits to the component's activation on 8k
training rows. Everything else predicts 0.
"""

READS = ()

TOP = {"td", "span", "div", "tr", "img"}
MID = {"th", "thead", "tbody", "button", "option", "strong", "svg", "textarea", "input",
       "li", "br", "table", "label", "form", "body", "hr", "link", "meta", "select", "dd",
       "dt", "dl"}
LOW = {"html", "head", "p", "a", "ul", "ol", "em", "b", "i", "u", "small", "sup", "sub",
       "code", "pre", "section", "header", "footer", "nav", "article", "aside", "main",
       "summary", "details", "path", "iframe", "canvas", "audio", "video", "source",
       "param", "object", "center", "font", "tt", "h", "h1", "h2", "h3", "h4", "h5", "h6",
       "script", "style", "title", "noscript", "fieldset", "legend", "figure", "blockquote"}
ATTRS = {"href", "onclick", "colspan", "rowspan"}
BARE = {"div", "span", "td", "img"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if len(prefix.document_ids) > 1 and prefix.document_ids[-2] != prefix.document_ids[-1]:
        prev = ""  # the previous token is in another document
    if tok == "else" and (prev.rstrip().endswith("}") or prev.strip() == ""):
        return None, 0.65
    closing = prev.endswith("</") or tok.startswith("</")
    opening = (prev.endswith("<") or tok.startswith("<")) and not closing
    name = tok.lstrip("</").lstrip("<").lower()
    if name in ATTRS:
        return None, 1.4
    if opening:
        if name in TOP:
            return None, 3.8
        if name in MID:
            return None, 2.0
        if name in LOW:
            return None, 1.1
    if closing:
        if name in TOP:
            return None, 2.4
        if name in MID:
            return None, 1.5
        if name in LOW:
            return None, 0.8
    if name in BARE:
        return None, 1.0
    return None, 0.0

