    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    text = token.strip()
    word = text.lstrip('._([{<,=-')
    name = word.lower()
    value = CHINESE.get(text, WORDS.get(name, 0.0))
    if name == 'float':
        if text.startswith('.'):
            value = 5.3 if word.islower() else 4.0
        elif text.startswith(('(', '[')):
            value = 4.5 if word.islower() and text[0] == '(' else 3.4
        elif word == 'Float':
            value = 4.5 if token == word else 3.85
        elif word == 'FLOAT':
            value = 3.55 if text.startswith('_') else 4.4
    elif name == 'floating' and (word[0].isupper() or token == word):
        value = 2.1
    elif name == 'double':
        if word[0].isupper():
            value = 2.0
        elif text.startswith('.'):
            value = 3.0
        elif text.startswith('('):
            value = 1.4
    elif name == 'string':
        if word[0].isupper():
            value = 0.65
        if text.startswith('('):
            value -= 0.08
