"""A first-layer lexical signal for delimiters and selected content-word families.

Chat/thought/tool markers are strongly positive; closing a normal message is
stronger than closing tool markup. Smaller signals mark named word classes:
bindings and data operations, attributes, portions/differences, political and
natural geography, and symbolic representations. Efficiency/effort words are
negative. Matching includes common stems and code identifiers, not token ids.
Other text gets small character-class baselines. Document starts are damped.
"""

import unicodedata
from functools import lru_cache

READS = ()
MARKERS = {
    '<|im_start|>': 2.51, '<|im_end|>': 4.36,
    '<think>': 3.49, '</think>': 3.70,
    '<tool_call>': 6.09, '</tool_call>': 2.66,
    '<tool_response>': 2.22, '</tool_response>': 4.02,
}

# Shared value, complete words, and productive word/identifier beginnings.
CLASSES = (
    (0.94, 'const var float none lambda'.split(),
     'constant variab function'.split()),
    (0.81, 'add adds added adding sum sums map maps mapping dict dictionary'.split(),
     'return export creat'.split()),
    (1.01, 'import imports imported importing api'.split(),
     'propert attribut field column header footer metadata plugin stream'.split()),
    (0.81, 'some sometimes various partial entire half fraction'.split(),
     'differ portion'.split()),
    (0.94, '''country countries international domestic foreign global worldwide
        american european canadian military army royal king queen prince princess
        emperor population tax taxes'''.split(),
     '''nation region territor province citizen immig govern feder polit
        president congress parliament legislat soldier officer veteran'''.split()),
    (1.04, 'land bay'.split(),
     'border coast island river mountain valley'.split()),
    (0.74, 'word words letter letters font fonts vector vectors scalar'.split(),
     'gradient dimension element translat'.split()),
    (1.02, 'across front middle'.split(), 'cross'.split()),
    (-0.40, 'intent helpful committed commitment'.split(),
     'effici effectiv effort achiev'.split()),
)

# Geographic, political and quantity words in Chinese.
CHINESE_GEOGRAPHY = set('国國山海河湖江島岛川田京都市省城港洲界') | {
    '国家', '國家', '地区', '地域', '城市',
}
CHINESE_GOVERNMENT = set('王皇帝君政官税稅军軍') | {
    '政府', '政治', '人民',
}
CHINESE_PORTIONS = {'一些', '有些', '不同', '一半', '半'}


@lru_cache(maxsize=32768)
def lexical_value(token):
    text = token.strip()
    word = text.lstrip('.(/,-;:=[').casefold()
    for value, words, stems in CLASSES:
        if word in words or any(word.startswith(stem) for stem in stems):
            return value
    if text in CHINESE_GEOGRAPHY:
        return 1.04
    if text in CHINESE_GOVERNMENT:
        return 0.94
    if text in CHINESE_PORTIONS:
        return 0.81
    if text in ('✓', '✔', '✅'):
        return 1.06
    if text and all('\u4e00' <= c <= '\u9fff' for c in text):
        return 0.18
    if not text or text.isdigit():
        return 0.01
    if all(unicodedata.category(c)[0] in 'PS' for c in text):
        return 0.01
    if word.isascii() and word.isalpha():
        if len(word) <= 2:
            return 0.01
        if text.lstrip('.(/,-;:=[')[0].isupper():
            if token[0].isspace():
                return 0.10 if len(word) <= 4 else 0.22
            return 0.05 if len(word) <= 4 else 0.11
        return 0.01 if len(word) <= 4 else 0.05 if len(word) <= 8 else 0.09
    return 0.08


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    value = MARKERS.get(token)
    if value is None:
        value = lexical_value(token)
    elif token == '<|im_end|>':
