"""Approximate a web-vocabulary component, not a general code detector.

URL/HTML terminology is strongest; web content and text tools are weaker.
Word-internal and code-prefixed spellings often respond more strongly than
space-leading words. Recent web vocabulary and explicit HTTP noun phrases
boost ambiguous words. Carry is reset at each new document.
"""
import re

READS = ()

# Semantic family, ordinary-word score, internal/code score, vocabulary.
RULES = (
    ('addresses', 1.5, 1.5, 'url uri href localhost'),
    ('protocols', 1.0, 1.1, 'http https www'),
    ('markup', 1.6, 1.6, 'html htm xhtml'),
    ('web_libraries', 2.4, 2.0, 'urllib urlparse beautifulsoup xpath crawler'),
    ('redirect', 2.6, 2.8, 'redirect'),
    ('web_interfaces', 1.6, 1.6,
     'servlet contenttype charset mime mimetype stylesheet iframe '
     'requestmapping requestparam responsebody responsewriter '
     'sitemap seo ajax cors cgi aspx jsp'),
    ('browsing', 0.7, 0.8,
     'web website webpage blog browser cookie click download wordpress '
     '网站 网址 本站 サイト сайт сайте 点击 下载'),
    ('content', 0.7, 0.9, 'content title page text 内容 页面 网页 ページ страниц'),
    ('site', 0.35, 0.65, 'site'),
    ('requests', 0.6, 0.9, 'request req header 请求 запрос'),
    ('replies', 0.2, 0.75, 'response resp body'),
    ('post', 0.35, 0.55, 'post'),
    ('text_tools', 0.5, 0.8,
     'link template render config format parse parser replace escape ignore'),
    ('paths', 0.35, 0.5, 'path directory dir index filename'),
    ('documents', 0.55, 0.6, 'document doc pdf xml json yaml yml markdown md'),
    ('web_elements', 0.3, 0.5, 'tag meta style css form src script php server'),
    ('generic_code', -0.1, -0.1, 'data file name class list node code string'),
)
WORDS = {word: name for name, *_, words in RULES for word in words.split()}
VALUES = {name: (plain, internal) for name, plain, internal, _ in RULES}
WEB_NOUNS = {'body', 'request', 'response', 'header', 'page', 'site', 'content'}
WEB_MODIFIERS = {'http', 'https', 'html', 'xml', 'json', 'url', 'web',
                 'request', 'response', 'post', 'get'}


def family(word):
    if word in WORDS:
        return WORDS[word]
    for suffix, ending in (('ies', 'y'), ('s', ''), ('ing', ''), ('ed', '')):
        if word.endswith(suffix):
            root = word[:-len(suffix)] + ending
            if root in WORDS:
                return WORDS[root]
    if word.startswith('url') or word.endswith('url'):
        return 'addresses'
    if word.startswith('http'):
        return 'protocols'
    if 'html' in word:
        return 'markup'
    if word.endswith(('request', 'header', 'headers')):
        return 'requests'
    if word.endswith('response'):
        return 'replies'
    if word.startswith(('getelement', 'getattribute', 'setattribute',
                        'getparameter', 'getsession', 'appendchild')):
        return 'web_interfaces'
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    topic, fragment = (0.0, '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    stripped = token.strip()
    core = stripped.lstrip('._-/(:<[$@\\')
    word = core.lower()
    group = family(word)
    internal = core != stripped or not token[:1].isspace()
    completed = False
    if group is None and core.isalpha() and fragment and not token[:1].isspace():
        joined = fragment + core
        if joined.lower() in WORDS:
            group, internal, completed = family(joined.lower()), True, True
    if core in ('GET', 'POST', 'DOM') or (word == 'dom' and core != stripped):
        group = 'web_interfaces'
    if word == 'md' and not stripped.startswith('.'):
        group = None
    score = VALUES.get(group, (0.0, 0.0))[int(internal)]
    if group in {'content', 'site', 'requests', 'replies', 'post'}:
        score += 0.5 * topic
    if completed:
        score *= 0.75
    if word in WEB_NOUNS and fragment.lower() in WEB_MODIFIERS:
        score = max(score, 1.6)
    if word == 'replace' and stripped.startswith('_'):
        score = 1.3
    if token == '<tool_response>':
        score = 0.76
    elif token in ('<|im_end|>', '<tool_call>', '</tool_response>'):
        score = -0.1
    elif token == '://':
        score = 0.45
    elif token == '<?':
        score = 0.8
    if token.isalpha():
        fragment = (fragment + token)[-32:]
    else:
        ending = re.search(r'[^\W\d_]+$', token)
        fragment = ending.group() if ending else ''
    strong = group in {'addresses', 'protocols', 'markup',
                       'web_libraries', 'browsing'}
    return (doc, max(0.85 * topic, float(strong)), fragment), float(score)

