READS = ()

# Necessity, duration, resource use, expenditure, and common translations.
GROUPS = (
    (.85, 'need needed require required requiring time 时间 時間 시간'),
    (1.05, 'requires complexity computational времени 耗 消耗 所需'),
    (.72, 'needs needing resources consumed consuming consumption intensive'),
    (.50, 'necessary unnecessary space complicated elapsed'),
    (.40, 'take took taken taking spend spending labor labour invest invested '
           'investing investment investments expenditure expenditures savings'),
    (.55, 'takes spent effort 需要 需求 投入 资源 資源 复杂 複雑 空间 空間'),
    (.25, 'resource memory storage money funds costs expense expenses expensive '
           'computation calculations usage complex runtime datetime requirements'),
    (.18, 'times cost save requirement budget 時 时 temps'),
    (.45, 'zeit время tiempo 花 费 費 占 佔'),
)
VALUES = {w: v for v, words in GROUPS for w in words.split()}
SPENDING = set('spend spent spending invest investing devote devoting waste '
               'wasted consume consuming take takes took taking require '
               'requires required need needed'.split())
COMPUTING = set('compute computing computational computation processing execution '
                'quadratic polynomial exponential linear algorithm running'.split())
MODALS = {'would', 'will', 'may', 'might', "'ll", '’ll'}
TAKING = {'take', 'takes', 'took', 'taken', 'taking'}
AMOUNT = {'much', 'more', 'less', 'total', 'average', 'enough', 'precious'}
RESOURCE = {'time', 'effort', 'efforts', 'resources', 'energy', 'capital', 'space'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = () if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    word = raw.strip().lstrip('_-.').lower()
    previous = recent[-1] if recent else ''

    def seen(words, n=3):
        return any(w in words for w in recent[-n:])

    value = VALUES.get(word, 0.0)
    if word in {'need', 'needed', 'require', 'requires', 'required', 'requiring'}:
        if recent:
            value -= .24 * (not raw.startswith(' '))
            value -= .18 * raw.strip()[0].isupper()
        if word in {'need', 'require'} and seen(MODALS, 2):
            value += .78
        if word in {'required', 'needed'} and seen(RESOURCE, 2):
            value += 1.3
    if word == 'time':
        value += .62 * seen(SPENDING, 5) + .51 * seen(COMPUTING)
        value += .45 * seen(AMOUNT, 2)
        value -= .65 * (previous in {'first', 'last', 'next', 'same'})
        value -= .25 * (previous in {'this', 'that', 'any', 'every'})
        value -= .50 * (seen({'at'}) or previous == 'from')
    if word in {'spent', 'taken', 'takes'} and seen({'time'}):
        value += 1.27
    if word in {'take', 'takes', 'taking'} and previous in MODALS:
        value += .36
    if word in {'cost', 'costs', 'resources', 'complexity', 'budget'}:
        value += 1.4 * seen(COMPUTING)
    if word in {'consuming', 'intensive'}:
        value += 1.64 * seen({'time', 'cpu', 'labor'}, 2)
    if word == 'consumption':
        value += .70 * seen({'energy', 'resource', 'resources'}, 2)
    if word in {'effort', 'space'}:
        value += .65 * seen({'time'})
    if word == 'up' and seen(TAKING, 2):
        value = .83
    if word == 'zone':
        value = -1.17 if previous == 'time' else -.15
    if word in {'的时间', '时间和'}:
        value = 1.15
    if raw in {' O', 'O'}:
        value = .25  # The O used in complexity notation.
    if not recent and value > .3:
        value *= 2.2
    return (doc, (recent + (word,))[-5:]), float(value)

"""A sparse Dan/丹 detector, with a secondary powder-and-pellet response.

丹 (dan, 'cinnabar' or 'elixir') is the strongest trigger. Latin Dan names
and Danish forms respond more weakly. Compounds such as 苏丹 (Sudan/sultan),
阿姆斯特丹 (Amsterdam), and 睾丸 (testicle) differ from the isolated
characters. Granular substances and a few pill-related forms give smaller
signals. Unlisted tokens return zero: this deliberately omits the many
small, diffuse lexical responses rather than hiding them in a token table.
A weak negative response is retained for time/day/week duration words.
"""
READS = ()

DAN_NAMES = {
    'Dan': 1.23,
    'Daniel': 0.90,
    'Daniels': 0.76,
    'Danny': 0.30,
    'Dani': 0.31,
    'Dana': 0.25,
    'Danielle': 0.26,
    'DAN': 0.79,
}
DANISH_FORMS = {'Denmark': 0.52, 'Danish': 0.38, '丹麦': 0.52}
GRANULES = {'pellet', 'pellets', 'gravel'}
DURATIONS = {'time': -0.088, 'days': -0.076, 'week': -0.117,
             'weeks': -0.032, 'day': -0.027}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, position = '', 0
    else:
        tail, position = carry[1], carry[2]
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    previous = tail.split()[-1].lower() if tail.split() else ''
    value = DAN_NAMES.get(word, DANISH_FORMS.get(word, 0.0))

    if token.startswith(' ') and word in DURATIONS:
        value = DURATIONS[word]
    elif word == '丹':
        value = 4.30
        if tail.endswith(('苏', '蘇')):
            value = 2.8
        elif tail.endswith('姆斯特'):
            value = 3.1
        elif tail.endswith(('炼', '煉')):
            value = 4.95
        elif position == 0:
            value = 4.99
    elif word == '丸':
        value = 0.44 if tail.endswith('睾') else 1.16
    elif word == 'dan':
        value = 0.39 if token.startswith(' ') else 0.53
    elif word == 'Dan' and not token.startswith(' '):
        value = 1.24 if position == 0 else 1.10
    elif word == 'Daniel' and position == 0:
        value = 1.23
    elif word == 'atonin':  # melatonin's tokenized ending
        value = 0.97
    elif lower in {'powder', 'powdered'}:
        value = 0.63 if previous == 'baking' else 0.51
    elif lower == 'combustion':
        value = 0.80 if previous == 'internal' else 0.44
    elif token.startswith(' ') and lower in GRANULES:
        value = 0.36
    elif token.startswith(' ') and lower in {'salt', 'salts'}:
        value = 0.23
    elif word == '粉':  # powder
        value = 0.23
    elif word == '牡丹':  # peony: 丹 inside a single compound token
        value = 0.19
    return (doc, (tail + token)[-24:], position + 1), value

programs.haiku:
"""Names starting with "Dan" and words for powders, pellets and granular materials.

Strong on the name Dan (and Daniel, Danny, Dana) and on the Chinese character 丹;
weaker on lowercase "dan" and on powder-like words. Everything else is 0."""
READS = ()

DAN_NAMES = {"dan", "daniel", "danny", "dana", "dans"}
POWDER_WORDS = {"powder", "powdered", "pellet", "pellets", "gravel", "granite", "salt",
                "combustion", "digest", "digestion"}

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    w = s.strip()
    if s == "丹":
        return None, 3.0
    if w in ("Dan", "Daniel", "Danny", "Dana"):
        return None, 1.2
    if w.lower() in DAN_NAMES:
        return None, 0.4
    if w.lower() in POWDER_WORDS:
        return None, 0.5
    return None, 0.0

programs.luna:
"""A conservative lexical approximation to the component's rare Dan response."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    lower = token.lower()
    if "丹" in token:
        return None, 1.2
    if lower.startswith("dan"):
        if lower.startswith("denmark"):
            return None, 0.16
        if lower.startswith("daniel"):
            return None, 0.27
        return None, 0.31
    return None, 0.0

programs.sol:
"""Approximate a negative spelling response to 'ug', plus document endings.

Bare 'ug' and its plural are strongest. Short consonant-onset ug endings
and doubled-g fragments are next; longer spellings weaken the response.
Cyrillic 'уг' is a weaker counterpart. 'Ugh' and 'debug' are excluded.
This token-local approximation leaves unrelated lexical responses at zero.
"""
READS = ()
CONSONANTS = frozenset("bcdfghjklmnpqrstvwxyz")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    # Spaces and common code punctuation do not change the spelling class.
    word = token.strip().lower().lstrip('_./-(')
    stem = word.removesuffix('s')
    if token == '<|endoftext|>':
        value = -1.37
    elif 'уг' in word:
        value = -1.3 if len(word) <= 3 else -0.5
    elif 'ug' not in word or 'ugh' in word or 'debug' in word:
        value = 0.0
    elif word == 'ug':
        if token[:1].isspace():
            value = -2.5
        else:
            value = -6.0 if token.isupper() else -4.8
    elif word == 'ugs':
        value = -4.6
    elif word.startswith('uggest') or word.startswith('sugg'):
        value = -1.0
    elif word.startswith('ugg') and word[3:] not in {'y', 'le', 'ling'}:
        value = -3.5
    elif word.endswith('ug') or word.endswith('ugs'):
        if word.startswith('aug'):
            value = -1.35 if token.strip().istitle() else -2.3
        elif word in {'drug', 'drugs', 'dug'}:
            value = -1.8
        elif len(stem) <= 4:
            onset = stem[:-2]
            if onset and all(c in CONSONANTS for c in onset):
                value = -3.4
            else:
                value = -1.7
        else:
            value = -0.5
    elif word.startswith('ug'):
        if word[2:3] in {'a', 'i', 'u'}:
            value = -3.0 if len(word) == 3 else -1.7
        else:
            value = -1.7
    elif word.startswith('bug') or word.startswith('rugged'):
        value = -1.8
    elif word in {'hugged', 'hugging', 'plugged', 'plugging'}:
        value = -2.6
    elif word.startswith('sugar'):
        value = -1.2
    elif word.startswith('august'):
        value = -0.4
    elif word.startswith('augment'):
        value = -1.1
    elif 'ouge' in word or word.startswith('portug'):
        value = 0.0
    else:
        value = -0.45
    return None, value

"""Vowel-initial spelling fragments, plus forms of 'at' and capitalized 'In'.

A consonant fragment joined to an isolated initial vowel (A + theros,
O + BS, or their Cyrillic/Greek counterparts) gets a positive value.
Word-internal splits are weaker. Arabic alif prefixes follow the same
pattern. Case, script and fragment length set the response's strength.
Other tokens are predicted near zero. Carry resets between documents.
"""
import unicodedata

READS = ()
VOWELS = frozenset('aeiouаеёиоуыэюяіїαεηιουω')
BOUNDARIES = ' \t\n\r-_/.(\"\'“[,=:;'
ALIF_STARTS = frozenset({
    'ا', 'أ', 'إ', 'آ', 'الأ', 'الإ', 'الآ',
    'والأ', 'والإ', 'فأ', 'بأ', 'لأ',
})


def unaccent(s):
    # Cyrillic й is a consonant: its breve is not merely an accent.
    if 'й' in s.lower():
        return s
    return ''.join(c for c in unicodedata.normalize('NFD', s)
                   if unicodedata.category(c) != 'Mn')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old, initial = '', False
    if carry is not None and carry[0] == doc:
        _, old, initial = carry
    s = prefix.token_strings[-1]
    at_boundary = bool(s and not s[0].isalpha()) or not old[-1:].isalpha()
    word = s.lstrip(BOUNDARIES)
    value = 0.0
    if word in {'at', 'At', 'In', 'AT'}:
        if word == 'at':
            if s[:1].isspace():
                value = 0.75
            else:
                value = 0.50 if at_boundary else 0.13
        elif word == 'At':
            value = 0.97 if at_boundary else 0.75
        elif word == 'In':
            value = 0.54 if at_boundary else 0.27
        else:
            value = 0.40 if at_boundary else 0.05
        if not old:
            value += 0.35
    elif s.isalpha():
        previous = old.lstrip(BOUNDARIES)
        vowel = unaccent(previous)
        if previous in ALIF_STARTS:
            value = 0.70 if initial else 0.40
            if previous.endswith('آ'):
                value = 0.30
        elif (1 <= len(vowel) <= 2
              and all(c.lower() in VOWELS for c in vowel)):
            if unaccent(s[0]).lower() in VOWELS:
                value = 0.20 if initial else -0.02
            elif initial or vowel[:1].isupper():
                value = 1.18 if vowel[:1].isupper() else 0.90
                if vowel in 'ei':
                    value = 0.40
                elif vowel in 'ou':
                    value = 0.70
                if s.isupper():
                    value = 0.28 if len(s) == 1 else 0.72
                script = unicodedata.name(s[0], '')
                if 'GREEK' in script:
                    value = 0.40
                elif 'CYRILLIC' in script:
                    value = 0.80 if s.islower() else 0.35
                elif s.islower() and (len(s) == 1 or len(s) > 4):
                    value *= 0.75
                elif not s.islower() and not s.isupper():
                    value = 0.25
            else:
                value = 0.18
    return (doc, s, at_boundary), value
